                  {url ? (
                    <a
                      href={val as string}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-[11px] text-sky-400/70 hover:text-sky-400 truncate block transition-colors"
                    >
                      {(val as string).replace(/^https?:\/\/(www\.)?/, "")}
                    </a>
                  ) : (
                    <p className="text-[12px] text-white/60 truncate">{val as string}</p>
                  )}
                </div>
              </div>
            ))}

            {lead.recommendedApproach && (
              <div className="pt-2.5 border-t space-y-1" style={{ borderColor: "rgba(255,255,255,.06)" }}>
                <div className="flex items-center justify-between gap-2">
                  <p className="text-[9px] font-black text-white/20 uppercase tracking-wide">Recommended AI Approach</p>
                  <span className="text-[8px] font-bold text-emerald-400 bg-emerald-400/5 border border-emerald-400/10 px-1.5 py-0.25 rounded lowercase shrink-0">saved in db</span>
                </div>
                <div className="flex items-center gap-1.5 mt-0.5">
                  <Sparkles className="size-3 text-emerald-400 shrink-0" />
                  <span
                    className="text-[10px] font-bold text-emerald-400 px-1.5 py-0.5 rounded"
                    style={{ background: "rgba(52,211,153,.1)" }}
                  >
                    {APPROACH_LABELS[lead.recommendedApproach] || lead.recommendedApproach}
                  </span>
                </div>
              </div>
            )}

            {lead.auditJson && (() => {
              try {
                const audit = JSON.parse(lead.auditJson)
                return (
                  <div className="pt-2.5 border-t space-y-1" style={{ borderColor: "rgba(255,255,255,.06)" }}>
                    <div className="flex items-center justify-between gap-2">
                      <p className="text-[9px] font-black text-white/20 uppercase tracking-wide">Website Audit</p>
                      <span className="text-[8px] font-bold text-emerald-400 bg-emerald-400/5 border border-emerald-400/10 px-1.5 py-0.25 rounded lowercase shrink-0">saved in db</span>
                    </div>
                    <div className="flex flex-wrap gap-1 mt-1">
                      <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded ${audit.ssl ? "text-emerald-400 bg-emerald-400/5 border border-emerald-400/10" : "text-red-400 bg-red-400/5 border border-red-400/10"}`}>
                        {audit.ssl ? "SSL" : "No SSL"}
                      </span>
                      <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded ${audit.speed < 2000 ? "text-emerald-400 bg-emerald-400/5 border border-emerald-400/10" : "text-amber-400 bg-amber-400/5 border border-amber-400/10"}`}>
                        {(audit.speed / 1000).toFixed(1)}s load
                      </span>
                      <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded ${audit.mobile ? "text-emerald-400 bg-emerald-400/5 border border-emerald-400/10" : "text-amber-400 bg-amber-400/5 border border-amber-400/10"}`}>
                        {audit.mobile ? "Mobile" : "No Mobile"}
                      </span>
                      {audit.pixel && (
                        <span className="text-[9px] font-bold px-1.5 py-0.5 rounded text-sky-400 bg-sky-400/5 border border-sky-400/10">
                          Pixel
                        </span>
                      )}
                    </div>
                  </div>
                )
              } catch { return null }
            })()}

            {lead.notes && (
              <div className="pt-2 border-t" style={{ borderColor: "rgba(255,255,255,.06)" }}>
                <p className="text-[9px] font-black text-white/20 uppercase tracking-wide mb-1">Notes</p>
                <p className="text-[11px] text-white/45 leading-relaxed whitespace-pre-wrap">{lead.notes}</p>
              </div>
            )}
          </div>

          {/* Pipeline + activities */}
          <LeadPipelinePanel
            leadId={lead.id}
            initialStatus={lead.status}
            initialDealValue={lead.dealValue ?? null}
            initialBattleCard={lead.battleCard ?? null}
            initialActivities={activities}
          />
        </div>

        {/* Right: tabs panel */}
        <div className="flex-1 overflow-y-auto p-4 lg:p-5">
          {/* Mobile: lead info (above tabs, only on mobile) */}
          <div
            className="lg:hidden rounded-2xl p-4 mb-4 space-y-2"
            style={{
              background: "rgba(255,255,255,.03)",
              border: "1px solid rgba(255,255,255,.07)",
            }}
          >
            {lead.company && <p className="text-[12px] font-semibold text-white/60"><Building2 className="size-3 inline mr-1.5 opacity-50" />{lead.company}</p>}
            <p className="text-[11px] text-white/35 font-mono">{lead.email}</p>
            {lead.website && (
              <a href={lead.website} target="_blank" rel="noopener noreferrer" className="text-[11px] text-sky-400/60 truncate block">
                {lead.website.replace(/^https?:\/\/(www\.)?/, "")}
              </a>
            )}
          </div>

          <LeadTabsPanel
            leadId={lead.id}
            leadEmail={lead.email}
            leadWebsite={lead.website ?? null}
            leadCompany={lead.company ?? null}
            emails={lead.emails}
            replies={replies}
            leadIndustry={lead.industry}
            auditJson={lead.auditJson}
            contactsJson={lead.contactsJson}
            linkedinProfilesJson={lead.linkedinProfilesJson}
            recommendedApproach={lead.recommendedApproach}
            icebreaker={lead.icebreaker}
            researchNotes={lead.researchNotes}
            painPoints={lead.painPoints}
            competitorAnalysis={lead.competitorAnalysis}
            buyingSignalsJson={lead.buyingSignalsJson}
            signalsCheckedAt={lead.signalsCheckedAt}
          />

          {/* Mobile: pipeline panel below tabs */}
          <div className="lg:hidden mt-4">
            <LeadPipelinePanel
              leadId={lead.id}
              initialStatus={lead.status}
              initialDealValue={lead.dealValue ?? null}
              initialBattleCard={lead.battleCard ?? null}
              initialActivities={activities}
            />
          </div>
        </div>
      </div>
    </div>
  )
}

"use client"

import { useEffect, useState } from "react"
import { usePlaybook } from "@/lib/playbook-context"
import { Briefcase, Target, FileText, CheckCircle2, MessageSquare, Plus, Trash2, X, Loader2, Save } from "lucide-react"
import { toast } from "sonner"

export default function PlaybooksPage() {
  const { activePlaybook } = usePlaybook()
  const [verticals, setVerticals] = useState<string[]>([])
  const [platforms, setPlatforms] = useState<string[]>([])
  const [objections, setObjections] = useState<Array<{ objection: string; response: string }>>([])

  const [newVertical, setNewVertical] = useState("")
  const [newPlatform, setNewPlatform] = useState("")
  const [saving, setSaving] = useState(false)

  // Sync state whenever activePlaybook loads or shifts
  useEffect(() => {
    if (activePlaybook) {
      setVerticals(activePlaybook.targetVerticals || [])
      setPlatforms(activePlaybook.platformOptions || [])
      setObjections(activePlaybook.objectionHandlers || [])
    }
  }, [activePlaybook])

  if (!activePlaybook) {
    return (
      <div className="flex h-96 items-center justify-center text-white/40 text-sm">
        <Loader2 className="size-5 animate-spin mr-2" />
        Loading playbook details...
      </div>
    )
  }

  // Verticals logic
  function addVertical() {
    const term = newVertical.trim().toLowerCase()
    if (!term) return
    if (verticals.includes(term)) {
      toast.error("Niche already targetable")
      return
    }
    setVerticals(prev => [...prev, term])
    setNewVertical("")
  }

  // Platforms logic
  function addPlatform() {
    const term = newPlatform.trim()
    if (!term) return
    if (platforms.includes(term)) {
      toast.error("Channel already configured")
      return
    }
    setPlatforms(prev => [...prev, term])
    setNewPlatform("")
  }

  // Objections logic
  function addObjection() {
    setObjections(prev => [...prev, { objection: "New Objection Text", response: "Strategy override response..." }])
  }

  function updateObjection(idx: number, key: "objection" | "response", val: string) {
    setObjections(prev => prev.map((item, i) => i === idx ? { ...item, [key]: val } : item))
  }

  // Save all settings
  async function handleSave() {
    if (!activePlaybook) return
    setSaving(true)
    try {
      const res = await fetch(`/api/playbooks/${activePlaybook.type}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          targetVerticals: verticals,
          platformOptions: platforms,
          objectionHandlers: objections
        })
      })
      if (!res.ok) throw new Error("Failed to save playbook settings")
      toast.success("Playbook configuration saved successfully!")
    } catch (err: any) {
      toast.error(err.message || "Could not save settings")
    } finally {
      setSaving(false)
    }
  }

  return (
    <div className="space-y-8">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pt-2">
        <div>
          <div className="flex items-center gap-2 mb-3">
            <span className="size-1.5 rounded-full bg-indigo-400" style={{ boxShadow: "0 0 6px rgba(129,140,248,.9)" }} />
            <span className="text-[10px] font-bold uppercase tracking-[.18em] text-white/25">
              Niche Settings
            </span>
          </div>
          <h1 className="text-[28px] font-black tracking-tight leading-none text-white/90">
            {activePlaybook.name} Config
          </h1>
          <p className="mt-2 text-[13px] text-white/25 font-medium">
            Calibrate target verticals, platforms, and AI objection handlers for automated campaigns
          </p>
        </div>

        <button
          onClick={handleSave}
          disabled={saving}
          className="shrink-0 inline-flex items-center gap-2 rounded-xl px-5 py-2.5 text-[12px] font-bold text-black transition-all hover:brightness-110 active:scale-[0.98] disabled:opacity-50"
          style={{
            background: "linear-gradient(135deg,#e2e5ed,#c8cdd8)",
            boxShadow: "0 2px 12px rgba(0,0,0,.3), inset 0 1px 0 rgba(255,255,255,.5)"
          }}
        >
          {saving ? (
            <Loader2 className="size-4 animate-spin" />
          ) : (
            <Save className="size-4" />
          )}
          {saving ? "Saving Changes…" : "Save Configuration"}
        </button>
      </div>

      <div className="grid gap-6 md:grid-cols-2">
        {/* Verticals */}
        <div 
          className="relative overflow-hidden rounded-2xl p-6 flex flex-col justify-between"
          style={{
            background: "linear-gradient(145deg,rgba(255,255,255,.04) 0%,rgba(255,255,255,.02) 100%)",
            border: "1px solid rgba(255,255,255,.07)",
          }}
        >
          <div>
            <div className="flex items-center gap-2 mb-4">
              <Target className="size-4 text-emerald-400" />
              <h2 className="text-sm font-semibold text-white">Target Verticals</h2>
            </div>
            <div className="flex flex-wrap gap-2">
              {verticals.length === 0 ? (
                <p className="text-xs text-white/20 italic">No target verticals added.</p>
              ) : (
                verticals.map((v) => (
                  <span 
                    key={v} 
                    className="inline-flex items-center gap-1.5 rounded-lg bg-emerald-500/10 border border-emerald-500/20 px-3 py-1 text-xs font-semibold text-emerald-400 capitalize"
                  >
                    {v}
                    <button 
                      type="button" 
                      onClick={() => setVerticals(prev => prev.filter(item => item !== v))} 
                      className="hover:text-emerald-200 text-emerald-400/55 transition-colors"
                    >
                      <X className="size-3" />
                    </button>
                  </span>
                ))
              )}
            </div>
          </div>

          <div className="flex gap-2 mt-5 max-w-sm">
            <input
              placeholder="Add niche vertical (e.g. spas)..."
              value={newVertical}
              onChange={e => setNewVertical(e.target.value)}
              className="flex-1 rounded-xl px-3.5 py-2 text-xs text-white/70 bg-black/30 border border-white/5 outline-none placeholder:text-white/15"
              onKeyDown={e => { if (e.key === "Enter") { e.preventDefault(); addVertical(); } }}
            />
            <button 
              onClick={addVertical} 
              className="p-2 rounded-xl bg-emerald-500/20 border border-emerald-500/30 text-emerald-400 hover:bg-emerald-500/30 transition-colors shrink-0"
            >
              <Plus className="size-4" />
            </button>
          </div>
        </div>

        {/* Discovery & Platforms */}
        <div 
          className="relative overflow-hidden rounded-2xl p-6 flex flex-col justify-between"
          style={{
            background: "linear-gradient(145deg,rgba(255,255,255,.04) 0%,rgba(255,255,255,.02) 100%)",
            border: "1px solid rgba(255,255,255,.07)",
          }}
        >
          <div>
            <div className="flex items-center gap-2 mb-4">
              <Briefcase className="size-4 text-indigo-400" />
              <h2 className="text-sm font-semibold text-white">Discovery Strategy</h2>
            </div>
            <div className="space-y-4">
              <div>
                <p className="text-[10px] uppercase font-bold tracking-wider text-white/35">Primary Discovery Method</p>
                <p className="text-xs text-white/70 capitalize mt-1.5">{activePlaybook.discoveryMethod} Search</p>
              </div>
              <div>
                <p className="text-[10px] uppercase font-bold tracking-wider text-white/35">Target Channels / Mediums</p>
                <div className="flex flex-wrap gap-2 mt-2">
                  {platforms.length === 0 ? (
                    <p className="text-xs text-white/20 italic">No channels added.</p>
                  ) : (
                    platforms.map((p) => (
                      <span 
                        key={p} 
                        className="inline-flex items-center gap-1.5 rounded-md bg-white/[0.04] px-2.5 py-1 text-[11px] text-white/60 border border-white/[0.06]"
                      >
                        {p}
                        <button 
                          type="button" 
                          onClick={() => setPlatforms(prev => prev.filter(item => item !== p))} 
                          className="hover:text-white text-white/20 transition-colors"
                        >
                          <X className="size-2.5" />
                        </button>
                      </span>
                    ))
                  )}
                </div>
              </div>
            </div>
          </div>

          <div className="flex gap-2 mt-5 max-w-sm">
            <input
              placeholder="Add target channel (e.g. Yelp)..."
              value={newPlatform}
              onChange={e => setNewPlatform(e.target.value)}
              className="flex-1 rounded-xl px-3.5 py-2 text-xs text-white/70 bg-black/30 border border-white/5 outline-none placeholder:text-white/15"
              onKeyDown={e => { if (e.key === "Enter") { e.preventDefault(); addPlatform(); } }}
            />
            <button 
              onClick={addPlatform} 
              className="p-2 rounded-xl bg-indigo-500/20 border border-indigo-500/30 text-indigo-400 hover:bg-indigo-500/30 transition-colors shrink-0"
            >
              <Plus className="size-4" />
            </button>
          </div>
        </div>
      </div>

      {/* Sequence Templates */}
      <div 
        className="relative overflow-hidden rounded-2xl p-6"
        style={{
          background: "linear-gradient(145deg,rgba(255,255,255,.04) 0%,rgba(255,255,255,.02) 100%)",
          border: "1px solid rgba(255,255,255,.07)",
        }}
      >
        <div className="flex items-center gap-2 mb-4">
          <CheckCircle2 className="size-4 text-amber-400" />
          <h2 className="text-sm font-semibold text-white">Preset Sequence Templates</h2>
        </div>
        <div className="grid gap-4 sm:grid-cols-2">
          {activePlaybook.sequenceTemplates.map((seq) => (
            <div key={seq.id} className="rounded-xl border border-white/[0.04] bg-white/[0.01] p-4 space-y-2">
              <div className="flex items-center justify-between">
                <h3 className="text-xs font-semibold text-white">{seq.name}</h3>
                <span className="text-[10px] bg-amber-500/10 text-amber-400 border border-amber-500/20 px-2.5 py-0.5 rounded-full font-bold">{seq.steps} steps</span>
              </div>
              <p className="text-xs text-white/40 leading-relaxed">{seq.description}</p>
            </div>
          ))}
        </div>
      </div>

      {/* Proposal Templates */}
      <div 
        className="relative overflow-hidden rounded-2xl p-6"
        style={{
          background: "linear-gradient(145deg,rgba(255,255,255,.04) 0%,rgba(255,255,255,.02) 100%)",
          border: "1px solid rgba(255,255,255,.07)",
        }}
      >
        <div className="flex items-center gap-2 mb-4">
          <FileText className="size-4 text-pink-400" />
          <h2 className="text-sm font-semibold text-white">Preset Proposal Pricing Packages</h2>
        </div>
        <div className="grid gap-4 sm:grid-cols-2">
          {activePlaybook.proposalTemplates.map((prop) => (
            <div key={prop.id} className="rounded-xl border border-white/[0.04] bg-white/[0.01] p-4 space-y-3">
              <div className="flex justify-between items-start">
                <div>
                  <h3 className="text-xs font-semibold text-white">{prop.name}</h3>
                  <p className="text-[11px] text-white/40 mt-1 leading-relaxed">{prop.description}</p>
                </div>
                <div className="text-right ml-4 shrink-0">
                  <p className="text-xs font-bold text-white">{prop.currency === "GBP" ? "£" : prop.currency}{prop.price}/{prop.period === "monthly" ? "mo" : "one-off"}</p>
                  {prop.setupPrice > 0 && (
                    <p className="text-[9px] text-white/30 mt-0.5">+{prop.currency === "GBP" ? "£" : prop.currency}{prop.setupPrice} setup</p>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Objection Handlers */}
      <div 
        className="relative overflow-hidden rounded-2xl p-6 space-y-4"
        style={{
          background: "linear-gradient(145deg,rgba(255,255,255,.04) 0%,rgba(255,255,255,.02) 100%)",
          border: "1px solid rgba(255,255,255,.07)",
        }}
      >
        <div className="flex items-center justify-between mb-2">
          <div className="flex items-center gap-2">
            <MessageSquare className="size-4 text-sky-400" />
            <h2 className="text-sm font-semibold text-white">Objection Overrides (AI Copilot overrides)</h2>
          </div>
          <button
            onClick={addObjection}
            className="flex items-center gap-1.5 text-[11px] font-bold text-sky-400 bg-sky-500/10 border border-sky-500/20 px-3 py-1.5 rounded-xl hover:bg-sky-500/20 transition-all shrink-0"
          >
            <Plus className="size-3.5" /> Add Objection
          </button>
        </div>

        <div className="space-y-4">
          {objections.length === 0 ? (
            <p className="text-xs text-white/20 italic p-3 text-center border border-dashed border-white/5 rounded-xl">
              No objection overrides. The AI will draft general positive replies.
            </p>
          ) : (
            objections.map((obj, idx) => (
              <div 
                key={idx} 
                className="rounded-xl border border-white/[0.04] bg-white/[0.01] p-4.5 space-y-3.5 relative group/objection"
              >
                <button 
                  onClick={() => setObjections(prev => prev.filter((_, i) => i !== idx))}
                  className="absolute top-3.5 right-3.5 opacity-0 group-hover/objection:opacity-100 p-1.5 text-white/25 hover:text-red-400/80 transition-all rounded-lg hover:bg-red-500/10 border border-transparent hover:border-red-500/10"
                >
                  <Trash2 className="size-4" />
                </button>
                <div className="space-y-1.5 max-w-xl">
                  <label className="text-[10px] font-bold text-rose-400/80 uppercase tracking-wider">Prospect Objection</label>
                  <input
                    value={obj.objection}
                    onChange={e => updateObjection(idx, "objection", e.target.value)}
                    className="w-full rounded-xl px-4 py-2 text-xs text-white/70 bg-black/25 border border-white/5 outline-none focus:border-white/15 placeholder:text-white/10"
                    placeholder="e.g. Already have an agency manager..."
                  />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-sky-400/80 uppercase tracking-wider">Override Response strategy / AI Guidelines</label>
                  <textarea
                    value={obj.response}
                    onChange={e => updateObjection(idx, "response", e.target.value)}
                    className="w-full min-h-[55px] rounded-xl px-4 py-2 text-xs text-white/60 bg-black/25 border border-white/5 outline-none focus:border-white/15 resize-none font-sans leading-relaxed placeholder:text-white/10"
                    placeholder="e.g. Work alongside existing manager to handle specialized visual production..."
                  />
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  )
}

"use client"

import { useState, useEffect } from "react"
import Link from "next/link"
import { usePlaybook } from "@/lib/playbook-context"
import { FileText, Plus, Loader2, Sparkles, ChevronRight } from "lucide-react"
import { toast } from "sonner"
import { CustomSelect } from "@/components/ui/custom-select"

type Lead = { id: string; firstName: string | null; lastName: string | null; company: string | null; email: string }
type Proposal = {
  id: string
  title: string
  status: string
  totalValue: number | null
  currency: string
  createdAt: string
  lead: { id: string; firstName: string | null; lastName: string | null; company: string | null; email: string }
}

const STATUS_STYLE: Record<string, { text: string; bg: string }> = {
  DRAFT:  { text: "text-white/40", bg: "rgba(255,255,255,.06)" },
  SENT:   { text: "text-sky-300", bg: "rgba(125,211,252,.1)" },
  VIEWED: { text: "text-amber-300", bg: "rgba(251,191,36,.1)" },
  SIGNED: { text: "text-emerald-400", bg: "rgba(52,211,153,.12)" },
  EXPIRED: { text: "text-red-400", bg: "rgba(239,68,68,.1)" },
}

function leadName(l: { firstName: string | null; lastName: string | null; company: string | null; email: string }) {
  return l.company || [l.firstName, l.lastName].filter(Boolean).join(" ") || l.email
}

export default function ProposalsPage() {
  const { activePlaybook } = usePlaybook()
  const [proposals, setProposals] = useState<Proposal[]>([])
  const [leads, setLeads] = useState<Lead[]>([])
  const [loading, setLoading] = useState(true)
  const [showCreate, setShowCreate] = useState(false)
  const [selectedLead, setSelectedLead] = useState("")
  const [selectedTemplate, setSelectedTemplate] = useState("")
  const [generating, setGenerating] = useState(false)

  async function load() {
    setLoading(true)
    try {
      const [p, l] = await Promise.all([
        fetch("/api/proposals").then(r => r.json()),
        fetch("/api/leads").then(r => r.json()),
      ])
      setProposals(Array.isArray(p) ? p : [])
      setLeads(Array.isArray(l) ? l : Array.isArray(l?.leads) ? l.leads : [])
    } catch { /* ignore */ }
    finally { setLoading(false) }
  }

  useEffect(() => { load() }, [])

  async function handleGenerate() {
    if (!selectedLead) { toast.error("Choose a lead first"); return }
    setGenerating(true)
    try {
      const res = await fetch("/api/proposals", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ leadId: selectedLead, templateId: selectedTemplate || undefined }),
      })
      const data = await res.json()
      if (!res.ok) throw new Error(data.error || "Failed")
      toast.success("Proposal generated")
      setShowCreate(false)
      setSelectedLead("")
      setSelectedTemplate("")
      await load()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Generation failed")
    } finally {
      setGenerating(false)
    }
  }

  return (
    <div className="space-y-8">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-white">Proposals</h1>
          <p className="text-sm text-white/40">AI-generated proposals built from your playbook templates and lead research.</p>
        </div>
        <button
          onClick={() => setShowCreate(s => !s)}
          className="flex items-center gap-2 rounded-xl bg-white/10 hover:bg-white/15 text-white text-xs font-semibold px-4 py-2 border border-white/[0.08] transition-all"
        >
          <Plus className="size-4" />
          <span>New Proposal</span>
        </button>
      </div>

      {showCreate && (
        <div className="rounded-2xl border border-white/[0.06] bg-white/[0.02] p-6 space-y-4" style={{ backdropFilter: "blur(12px)" }}>
          <div className="flex items-center gap-2 border-b border-white/[0.04] pb-3">
            <Sparkles className="size-4 text-violet-400" />
            <h2 className="text-sm font-semibold text-white">Generate from {activePlaybook?.name} templates</h2>
          </div>
          <div className="grid gap-3 sm:grid-cols-2">
            <CustomSelect
              value={selectedLead}
              onChange={setSelectedLead}
              placeholder="Choose a lead…"
              options={leads.map(l => ({ value: l.id, label: leadName(l) }))}
            />
            <CustomSelect
              value={selectedTemplate}
              onChange={setSelectedTemplate}
              placeholder={activePlaybook?.proposalTemplates?.[0]?.name || "Default template"}
              options={(activePlaybook?.proposalTemplates || []).map(t => ({ value: t.id, label: `${t.name} — ${t.currency === "GBP" ? "£" : t.currency}${t.price}/${t.period === "monthly" ? "mo" : "one-off"}` }))}
            />
          </div>
          <button
            onClick={handleGenerate}
            disabled={generating || !selectedLead}
            className="flex items-center gap-2 rounded-xl bg-violet-500/20 hover:bg-violet-500/30 text-violet-200 text-xs font-semibold px-4 py-2 border border-violet-500/30 transition-all disabled:opacity-40"
          >
            {generating ? <Loader2 className="size-4 animate-spin" /> : <Sparkles className="size-4" />}
            {generating ? "Generating…" : "Generate Proposal"}
          </button>
        </div>
      )}

      <div className="rounded-2xl border border-white/[0.06] bg-white/[0.02] overflow-hidden" style={{ backdropFilter: "blur(12px)" }}>
        <div className="flex items-center gap-2 border-b border-white/[0.04] px-6 py-4">
          <FileText className="size-4 text-pink-400" />
          <h2 className="text-sm font-semibold text-white">All Proposals</h2>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-16 text-white/30">
            <Loader2 className="size-5 animate-spin" />
          </div>
        ) : proposals.length === 0 ? (
          <div className="flex flex-col items-center justify-center text-center px-8 py-16 gap-3">
            <FileText className="size-8 text-white/15" />
            <p className="text-[13px] font-bold text-white/30">No proposals yet</p>
            <p className="text-[11px] text-white/20 max-w-sm">Generate one from a lead using your active playbook&apos;s templates and pricing.</p>
          </div>
        ) : (
          <div className="divide-y divide-white/[0.04]">
            {proposals.map(p => {
              const style = STATUS_STYLE[p.status] ?? STATUS_STYLE.DRAFT
              return (
                <Link
                  key={p.id}
                  href={`/proposals/${p.id}`}
                  className="flex items-center justify-between gap-4 px-6 py-4 hover:bg-white/[0.02] transition-colors"
                >
                  <div className="min-w-0">
                    <p className="text-[13px] font-semibold text-white truncate">{p.title}</p>
                    <p className="text-[11px] text-white/35 truncate">{leadName(p.lead)}</p>
                  </div>
                  <div className="flex items-center gap-3 shrink-0">
                    {p.totalValue != null && (
                      <span className="text-xs font-bold text-white/60">
                        {p.currency === "GBP" ? "£" : p.currency}{p.totalValue.toLocaleString()}
                      </span>
                    )}
                    <span className={`text-[9px] font-black uppercase tracking-wider px-2 py-0.5 rounded-full ${style.text}`} style={{ background: style.bg }}>
                      {p.status}
                    </span>
                    <ChevronRight className="size-4 text-white/20" />
                  </div>
                </Link>
              )
            })}
          </div>
        )}
      </div>
    </div>
  )
}

