        ) : sequences.length === 0 ? (
          <div
            className="flex flex-col items-center justify-center rounded-2xl py-14 text-center"
            style={{ background: "rgba(255,255,255,.02)", border: "1px dashed rgba(255,255,255,.07)" }}
