import { NextRequest, NextResponse } from "next/server"
import { auth } from "@/auth"
import { prisma } from "@/lib/db"
import { drainDueQueue } from "@/lib/scheduler"

/**
 * POST /api/process-queue
 * Manually drains all due QUEUED emails and auto-promotes expired follow-up drafts.
 * Can be called from the UI (stuck emails button) or hit directly in dev.
 */
export async function POST(req: NextRequest) {
  const session = await auth()
  if (!session?.user?.id) return NextResponse.json({ error: "Unauthorized" }, { status: 401 })

  try {
    // Reset FAILED emails for this user's leads to QUEUED so they can be retried
    const userLeads = await prisma.lead.findMany({
      where: { userId: session.user.id },
      select: { id: true },
    })
    const leadIds = userLeads.map(l => l.id)

    if (leadIds.length > 0) {
      await prisma.email.updateMany({
        where: {
          status: "FAILED",
          leadId: { in: leadIds },
        },
        data: {
          status: "QUEUED",
          scheduledAt: new Date(),
        },
      })
    }

    const results = await drainDueQueue()
    return NextResponse.json({
      success: true,
      ...results,
      message: `Sent ${results.sent}, auto-promoted ${results.autoPromoted} follow-ups, failed ${results.failed}`,
    })
  } catch (err) {
    console.error("[Process Queue] Error:", err)
    return NextResponse.json({ error: "Queue processing failed" }, { status: 500 })
  }
}

// Also support GET for quick manual hits during dev (e.g. browser tab)
export async function GET(req: NextRequest) {
  const secret = req.nextUrl.searchParams.get("secret")
  if (secret !== process.env.CRON_SECRET && process.env.NODE_ENV === "production") {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 })
  }

  try {
    const results = await drainDueQueue()
    return NextResponse.json({ success: true, ...results })
  } catch (err) {
    console.error("[Process Queue GET] Error:", err)
    return NextResponse.json({ error: "Failed" }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from "next/server"
import { auth } from "@/auth"
import { prisma } from "@/lib/db"

export async function PATCH(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const session = await auth()
  if (!session?.user?.id) return NextResponse.json({ error: "Unauthorized" }, { status: 401 })

  const { id } = await params
  const { name, steps } = await req.json()
  if (!name?.trim()) return NextResponse.json({ error: "Name required" }, { status: 400 })

  // Verify ownership
  const existing = await prisma.sequence.findFirst({
    where: { id, userId: session.user.id },
  })
  if (!existing) return NextResponse.json({ error: "Sequence not found" }, { status: 404 })

  if (steps && Array.isArray(steps)) {
    await prisma.$transaction([
      prisma.sequenceStep.deleteMany({ where: { sequenceId: id } }),
      prisma.sequence.update({
        where: { id, userId: session.user.id },
        data: {
          name: name.trim(),
          steps: {
            createMany: {
              data: steps.map((s: { stepNumber: number; delayDays: number; subjectTemplate?: string | null; bodyTemplate?: string | null; stepType?: any; aiPrompt?: string | null }) => ({
                stepNumber: s.stepNumber,
                delayDays: s.delayDays,
                subjectTemplate: s.subjectTemplate || null,
                bodyTemplate: s.bodyTemplate || null,
                stepType: s.stepType || "EMAIL",
                aiPrompt: s.aiPrompt || null,
              })),
            },
          },
        },
      }),
    ])
  } else {
    await prisma.sequence.update({
      where: { id, userId: session.user.id },
      data: { name: name.trim() },
    })
  }

  const updatedSequence = await prisma.sequence.findUnique({
    where: { id },
    include: { steps: { orderBy: { stepNumber: "asc" } } },
  })

  return NextResponse.json(updatedSequence)
}

export async function DELETE(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const session = await auth()
  if (!session?.user?.id) return NextResponse.json({ error: "Unauthorized" }, { status: 401 })

  const { id } = await params
  await prisma.sequence.deleteMany({ where: { id, userId: session.user.id } })
  return NextResponse.json({ deleted: true })
}

