  EMAIL_OPENED:          { icon: Star,          color: "text-amber-400",   label: "Opened"         },
  EMAIL_CLICKED:         { icon: ChevronRight,  color: "text-emerald-400", label: "Clicked"        },
  REPLY_RECEIVED:        { icon: MessageSquare, color: "text-violet-400",  label: "Reply"          },
  STAGE_CHANGED:         { icon: Zap,           color: "text-white/40",    label: "Stage Changed"  },
  NOTE_ADDED:            { icon: FileText,      color: "text-white/55",    label: "Note"           },
  MEETING_BOOKED:        { icon: Calendar,      color: "text-emerald-400", label: "Meeting Booked" },
  BATTLE_CARD_GENERATED: { icon: Sparkles,      color: "text-amber-400",   label: "AI Drafted"     },
}

const LEAD_STATUS: Record<string, string> = {
  NEW:           "rgba(255,255,255,.3)",
  CONTACTED:     "rgba(125,211,252,.7)",
  REPLIED:       "rgba(167,139,250,.8)",
  INTERESTED:    "rgba(52,211,153,.8)",
  MEETING_BOOKED:"rgba(251,191,36,.8)",
  WON:           "rgba(52,211,153,1)",
  LOST:          "rgba(248,113,113,.6)",
  NOT_INTERESTED:"rgba(248,113,113,.6)",
  BOUNCED:       "rgba(248,113,113,.5)",
}

const APPROACHES = [
  { id: "website", label: "Website Audit" },
  { id: "local-rank", label: "Local Rank" },
  { id: "competitor", label: "Competitor Pattern" },
  { id: "industry", label: "Industry Shift" },
  { id: "question", label: "Question Open" },
  { id: "social-proof", label: "Social Proof" },
  { id: "local-neighbor", label: "Local Neighbor (B2C)" },
]

// ── Lead row with step timeline ───────────────────────────────────────────────

function LeadRow({
  lead, sequenceSteps, campaignId, isLast, onUpdateLead,
}: {
  lead: Lead; sequenceSteps: SequenceStep[]; campaignId: string; isLast: boolean; onUpdateLead: (updated: Lead) => void
}) {
  const [expanded, setExpanded]   = useState(false)
  const [preview, setPreview]     = useState<EmailRecord[] | null>(null)
  const [loadingPrev, setLoading] = useState(false)
  const [activeStep, setActiveStep] = useState(1)

  const [emails, setEmails] = useState<EmailRecord[]>(lead.emails)
  const [approach, setApproach] = useState(lead.recommendedApproach || "website")
  const [generating, setGenerating] = useState(false)

  const [isEditing, setIsEditing] = useState(false)
  const [editSubject, setEditSubject] = useState("")
  const [editBody, setEditBody] = useState("")
  const [refinePrompt, setRefinePrompt] = useState("")
  const [savingEdits, setSavingEdits] = useState(false)
  const [refiningAI, setRefiningAI] = useState(false)
  const [queuingLead, setQueuingLead] = useState(false)

  // Sync state if lead prop changes
  useEffect(() => {
    Promise.resolve().then(() => setEmails(lead.emails))
  }, [lead.emails])

  const name        = [lead.firstName, lead.lastName].filter(Boolean).join(" ") || lead.email
  const sentEmails  = emails
  const leadColor   = LEAD_STATUS[lead.status] ?? LEAD_STATUS.NEW

  // Get the furthest email status for the header badge
  const priority = ["REPLIED", "CLICKED", "OPENED", "DELIVERED", "SENT", "QUEUED", "DRAFT", "BOUNCED", "FAILED"]
  const _topStatus = priority.find(s => sentEmails.some(e => e.status === s)) ?? (sentEmails.length === 0 ? "NEW" : "SENT")

  async function loadPreview(force = false) {
    if (preview && !force) return
    setLoading(true)
    try {
      const res = await fetch(`/api/send`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ campaignId, leadId: lead.id, preview: true }),
      })
      if (res.ok) {
        const data = await res.json()
        const emailList = Array.isArray(data) ? data : (data.emails ?? [])
        setPreview(emailList)
        setActiveStep(emailList[0]?.stepNumber ?? 1)
      }
    } catch { /* silent */ }
    finally { setLoading(false) }
  }

  function toggle() {
    setExpanded(e => !e)
    if (!expanded && !preview && emails.length === 0) loadPreview()
  }

  const activeEmail = emails.find(e => e.stepNumber === activeStep)

  async function handleSaveEdits() {
    if (!activeEmail) return
    setSavingEdits(true)
    try {
      const res = await fetch(`/api/emails/${activeEmail.id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ subject: editSubject, body: editBody }),
      })
      if (res.ok) {
        toast.success("Draft updated successfully")
        const updatedEmails = emails.map(e => e.id === activeEmail.id ? { ...e, subject: editSubject, body: editBody } : e)
        setEmails(updatedEmails)
        onUpdateLead({ ...lead, emails: updatedEmails })
        setIsEditing(false)
      } else {
        toast.error("Failed to save changes")
      }
    } catch {
      toast.error("Failed to save changes")
    } finally {
      setSavingEdits(false)
    }
  }

  async function handleRefineAI() {
    if (!activeEmail) return
    setRefiningAI(true)
    try {
      const res = await fetch(`/api/emails/${activeEmail.id}/refine`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ instruction: refinePrompt }),
      })
      if (res.ok) {
        const data = await res.json()
        toast.success("AI refined email draft!")
        const updatedEmails = emails.map(e => e.id === activeEmail.id ? { ...e, subject: data.email.subject, body: data.email.body } : e)
        setEmails(updatedEmails)
        onUpdateLead({ ...lead, emails: updatedEmails })
        setEditSubject(data.email.subject)
        setEditBody(data.email.body)
        setRefinePrompt("")
        setIsEditing(false)
      } else {
        toast.error("AI refinement failed")
      }
    } catch {
      toast.error("AI refinement failed")
    } finally {
      setRefiningAI(false)
    }
  }

  async function handleQueueLead() {
    setQueuingLead(true)
    try {
      const res = await fetch(`/api/campaigns/${campaignId}/leads/${lead.id}/queue`, {
        method: "POST",
      })
      if (res.ok) {
        const data = await res.json()
        toast.success("✅ Email sent successfully!")
        const updatedEmails = emails.map(e =>
          e.id === data.email?.id ? { ...e, status: data.email.status ?? "SENT", sentAt: data.email.sentAt } : e
        )
        setEmails(updatedEmails)
        onUpdateLead({ ...lead, emails: updatedEmails })
      } else {
        const err = await res.json().catch(() => ({}))
        toast.error((err as { error?: string }).error || "Failed to send email")
      }
    } catch {
      toast.error("Failed to send email")
    } finally {
      setQueuingLead(false)
    }
  }


  async function handleGenerateDrafts(selectedApproach: string) {
    setGenerating(true)
    try {
      const res = await fetch(`/api/campaigns/${campaignId}/leads/${lead.id}/generate-drafts`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ approach: selectedApproach }),
      })
      if (res.ok) {
        const data = await res.json()
        toast.success("Outreach drafts generated successfully!")
        setEmails(data.emails)
        onUpdateLead({ ...lead, emails: data.emails })
        setActiveStep(1)
        setIsEditing(false)
      } else {
        toast.error("Failed to generate drafts")
      }
    } catch {
      toast.error("Failed to generate drafts")
    } finally {
      setGenerating(false)
    }
  }

  async function handleStopEnrichment(e: React.MouseEvent) {
    e.stopPropagation() // Prevent row expansion
    try {
      const res = await fetch(`/api/leads/${lead.id}/stop-enrichment`, {
        method: "POST",
      })
      if (res.ok) {
        toast.success("Enrichment stopped")
        onUpdateLead({ ...lead, contactsJson: "[]" })
      } else {
        toast.error("Failed to stop enrichment")
      }
    } catch {
      toast.error("An error occurred")
    }
  }

  const showOutreachDesigner = emails.length === 0 || emails.every(e => e.status === "DRAFT")

  return (
    <div style={{ borderBottom: isLast ? "none" : "1px solid rgba(255,255,255,.04)" }}>
      {/* Row */}
      <div
        onClick={toggle}
        className="grid items-center gap-3 px-5 py-3.5 hover:bg-white/[.015] cursor-pointer transition-colors group"
        style={{ gridTemplateColumns: "minmax(0,2fr) minmax(0,2fr) minmax(0,1.2fr) 52px 96px 28px" }}
      >
        {/* Name */}
        <div className="flex items-center gap-2.5 min-w-0">
          <div
            className="flex size-7 shrink-0 items-center justify-center rounded-full text-[10px] font-bold text-white/60"
            style={{ background: "rgba(255,255,255,.06)", border: "1px solid rgba(255,255,255,.08)" }}
          >
            {initials(name)}
          </div>
          <p className="text-[13px] font-semibold text-white/80 truncate">{name}</p>
        </div>

        {/* Email */}
        <p className="hidden sm:block text-[11px] text-white/35 truncate">{lead.email}</p>

        {/* Company */}
        <p className="hidden md:block text-[12px] text-white/30 truncate">{lead.company ?? "—"}</p>

        {/* Step progress dots */}
        <div className="hidden sm:flex items-center gap-1">
          {sequenceSteps.map((step, i) => {
            const email = sentEmails.find(e => e.stepNumber === step.stepNumber)
            const isOpened = email && ["OPENED", "CLICKED", "REPLIED"].includes(email.status)
            const isSent   = email && ["SENT", "DELIVERED", "QUEUED"].includes(email.status)
            const isDraft  = email && email.status === "DRAFT"
            const isActive = isSent || isOpened

            return (
              <div key={i}
                className="size-2 rounded-full transition-all"
                style={{
                  background: isOpened ? "#34d399"
                    : isDraft ? "#fbbf24"
                    : isActive ? "rgba(255,255,255,.35)"
                    : "rgba(255,255,255,.1)",
                  boxShadow: isOpened ? "0 0 4px rgba(52,211,153,.6)" : isDraft ? "0 0 4px rgba(251,191,36,.5)" : "none",
                }}
              />
            )
          })}
        </div>

        {/* Status badge */}
        {lead.status === "NEW" && !lead.contactsJson ? (
          <div className="flex items-center gap-1.5 min-w-0">
            <span
              className="text-[10px] font-bold uppercase tracking-wide truncate flex items-center gap-1 text-emerald-400"
              title="Enriching contacts, LinkedIn profiles, and website audit details in the background..."
            >
              <Loader2 className="size-3 animate-spin text-emerald-400 shrink-0" />
              Enriching...
            </span>
            <button
              onClick={handleStopEnrichment}
              className="text-[9px] font-black uppercase tracking-wider text-red-400 hover:text-red-300 bg-red-500/10 hover:bg-red-500/20 border border-red-500/25 px-1.5 py-0.5 rounded transition-all opacity-0 group-hover:opacity-100 select-none shrink-0"
              title="Stop enrichment for this lead"
            >
              Stop
            </button>
          </div>
        ) : (
          <span
            className="text-[10px] font-bold uppercase tracking-wide truncate"
            style={{ color: leadColor }}
          >
            {lead.status.replace(/_/g, " ")}
          </span>
        )}

        {/* Expand */}
        <div className="flex justify-end text-white/20">
          {loadingPrev ? <Loader2 className="size-4 animate-spin" /> : expanded ? <ChevronDown className="size-4" /> : <ChevronRight className="size-4" />}
        </div>
      </div>

      {/* Expanded: step-by-step timeline */}
      {expanded && (
        <div className="px-5 pb-4">
          <div
            className="rounded-xl overflow-hidden"
            style={{ border: "1px solid rgba(255,255,255,.07)", background: "rgba(255,255,255,.02)" }}
          >
            {/* Approach selection bar for drafts */}
            {showOutreachDesigner && (
              <div className="flex items-center justify-between px-5 py-3 border-b flex-wrap gap-2.5" style={{ borderColor: "rgba(255,255,255,.05)", background: "rgba(255,255,255,.01)" }}>
                <div className="flex items-center gap-1.5">
                  <Sparkles className="size-3.5 text-emerald-400" />
                  <span className="text-[10px] font-black text-white/30 uppercase tracking-widest">Outreach Approach</span>
                </div>
                <div className="flex items-center gap-2">
                  <select
                    value={approach}
                    onChange={(e) => setApproach(e.target.value)}
                    className="bg-white/[.03] border border-white/[.08] rounded-lg px-2.5 py-1 text-[11px] text-white/70 outline-none cursor-pointer hover:bg-white/[.06] transition-all"
                  >
                    {APPROACHES.map(a => (
                      <option key={a.id} value={a.id} className="bg-[#0f172a] text-white/80">
                        {a.label}
                      </option>
                    ))}
                  </select>
                  <button
                    onClick={() => handleGenerateDrafts(approach)}
                    disabled={generating}
                    className="flex items-center gap-1.5 rounded-lg px-3 py-1 text-[11px] font-bold text-black bg-emerald-400 hover:brightness-110 disabled:opacity-40 transition-all select-none font-sans"
                  >
                    {generating ? <Loader2 className="size-3 animate-spin text-black" /> : <Zap className="size-3 text-black fill-current" />}
                    Generate Drafts
                  </button>
                </div>
              </div>
            )}

            {emails.length === 0 ? (
              <div className="px-5 py-8 text-center space-y-2">
                <p className="text-[12px] font-semibold text-white/30">No drafts generated for this lead yet.</p>
                <p className="text-[11px] text-white/20">Select an outreach approach above and click &quot;Generate Drafts&quot; to build personalized email cadences.</p>
              </div>
            ) : (
              <>
                {/* Step tabs */}
                <div className="flex border-b" style={{ borderColor: "rgba(255,255,255,.06)" }}>
                  {sequenceSteps.map(step => {
                    const email    = sentEmails.find(e => e.stepNumber === step.stepNumber)
                    const previewE = (preview ?? []).find(e => e.stepNumber === step.stepNumber)
                    const isActive = activeStep === step.stepNumber
                    const _isOpened = email && ["OPENED", "CLICKED", "REPLIED"].includes(email.status)
                    const _isSent   = email && email.status !== "FAILED"

                    return (
                      <button
                        key={step.stepNumber}
                        onClick={() => {
                          setActiveStep(step.stepNumber)
                          setIsEditing(false)
                        }}
                        className="flex-1 flex flex-col items-center gap-0.5 px-3 py-2.5 transition-all text-left"
                        style={{
                          background: isActive ? "rgba(255,255,255,.05)" : "transparent",
                          borderBottom: isActive ? "2px solid rgba(255,255,255,.3)" : "2px solid transparent",
                        }}
                      >
                        <span className="text-[9px] font-black text-white/30 uppercase tracking-wider">
                          {STEP_DAY[step.stepNumber] ?? `Step ${step.stepNumber}`}
                        </span>
                        {email ? (
                          <span className={`text-[10px] font-bold ${EMAIL_STATUS[email.status]?.color ?? "text-white/40"}`}>
                            {EMAIL_STATUS[email.status]?.label ?? email.status}
                            {email.openCount > 1 && ` ×${email.openCount}`}
                          </span>
                        ) : previewE ? (
                          <span className="text-[10px] text-white/20">Preview</span>
                        ) : (
                          <span className="text-[10px] text-white/20">Pending</span>
                        )}
                      </button>
                    )
                  })}
                </div>

                {/* Email content for active step */}
                {(() => {
                  const email    = sentEmails.find(e => e.stepNumber === activeStep)
                  const previewE = (preview ?? []).find(e => e.stepNumber === activeStep)
                  const data = email ?? previewE

                  if (!data) return (
                    <div className="px-5 py-6 text-center">
                      <p className="text-[11px] text-white/25">Email not sent yet — will be scheduled automatically</p>
                    </div>
                  )

                  const isDraft = data.status === "DRAFT"

                  return (
                    <div className="px-5 py-4 space-y-4">
                      {/* Metadata & Actions row */}
                      <div className="flex items-center justify-between flex-wrap gap-2 text-[10px] text-white/25">
                        <div className="flex items-center gap-3">
                          {email?.sentAt && <span>Sent {new Date(email.sentAt).toLocaleDateString("en-GB", { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" })}</span>}
                          {email && !email.sentAt && <span className="font-semibold text-amber-400/80">Draft Outreach</span>}
                          {!email && <span className="italic">Preview (not yet sent)</span>}
                          {email && email.openCount > 0 && <span className="text-emerald-400/70">· Opened {email.openCount}×</span>}
                          {email && email.clickCount > 0 && <span className="text-sky-400/70">· Clicked {email.clickCount}×</span>}
                        </div>

                        {isDraft && (
                          <div className="flex items-center gap-2">
                            <button
                              onClick={() => {
                                setEditSubject(data.subject)
                                setEditBody(data.body)
                                setIsEditing(prev => !prev)
                                setRefinePrompt("")
                              }}
                              className="px-2 py-1 rounded bg-white/5 border border-white/10 hover:bg-white/10 text-white/60 font-semibold uppercase tracking-wider text-[9px] transition-all font-sans"
                            >
                              {isEditing ? "Cancel" : "Edit Draft"}
                            </button>
                            <button
                              onClick={handleQueueLead}
                              disabled={queuingLead}
                              className="flex items-center gap-1 px-3 py-1 rounded bg-emerald-400 hover:brightness-110 disabled:opacity-40 text-black font-black uppercase tracking-wider text-[9px] transition-all font-sans"
                            >
                              {queuingLead ? <Loader2 className="size-3 animate-spin text-black" /> : <Send className="size-3 text-black" />}
                              {queuingLead ? "Sending..." : "Send Now"}
                            </button>
                          </div>
                        )}
                      </div>

                      {isEditing && isDraft ? (
                        /* Edit Form */
                        <div className="space-y-3.5 p-4 rounded-xl bg-black/20 border border-white/[.04]">
                          <div className="space-y-1">
                            <label className="text-[9px] font-black text-white/30 uppercase tracking-wider">Subject</label>
                            <input
                              value={editSubject}
                              onChange={e => setEditSubject(e.target.value)}
                              className="w-full bg-white/[.03] border border-white/[.08] rounded-lg px-3 py-1.5 text-[12px] text-white/80 outline-none"
                            />
                          </div>
                          <div className="space-y-1">
                            <label className="text-[9px] font-black text-white/30 uppercase tracking-wider">Body</label>
                            <textarea
                              value={editBody}
                              onChange={e => setEditBody(e.target.value)}
                              rows={6}
                              className="w-full bg-white/[.03] border border-white/[.08] rounded-lg px-3 py-2 text-[12px] text-white/70 outline-none leading-relaxed font-sans"
                            />
                          </div>

                          {/* AI Refinement Box */}
                          <div className="pt-2.5 border-t border-white/[.05] space-y-2">
                            <label className="text-[9px] font-black text-emerald-400/80 uppercase tracking-wider flex items-center gap-1">
                              <Sparkles className="size-3 text-emerald-400 fill-current" /> AI Refinement instruction
                            </label>
                            <div className="flex gap-2">
                              <input
                                placeholder="e.g. 'Make it more direct', 'Mention a 10% discount'"
                                value={refinePrompt}
                                onChange={e => setRefinePrompt(e.target.value)}
                                className="flex-1 bg-white/[.03] border border-white/[.08] rounded-lg px-3 py-1.5 text-[11px] text-white/70 outline-none placeholder:text-white/20"
                              />
                              <button
                                onClick={handleRefineAI}
                                disabled={refiningAI || !refinePrompt.trim()}
                                className="flex items-center gap-1 px-3 py-1.5 rounded-lg text-black bg-emerald-400 hover:brightness-110 disabled:opacity-30 text-[11px] font-bold transition-all font-sans"
                              >
                                {refiningAI ? <Loader2 className="size-3 animate-spin text-black" /> : <Sparkles className="size-3 text-black fill-current" />}
                                Refine
                              </button>
                            </div>
                          </div>

                          <div className="flex justify-end gap-2 pt-2 border-t border-white/[.03]">
                            <button
                              onClick={() => setIsEditing(false)}
                              className="px-3 py-1.5 rounded-lg text-white/40 hover:text-white/60 text-[11px] font-bold"
                            >
                              Cancel
                            </button>
                            <button
                              onClick={handleSaveEdits}
                              disabled={savingEdits}
                              className="flex items-center gap-1 px-4 py-1.5 rounded-lg text-white bg-white/10 hover:bg-white/15 text-[11px] font-bold border border-white/10 font-sans"
                            >
                              {savingEdits && <Loader2 className="size-3 animate-spin" />}
                              Save Changes
                            </button>
                          </div>
                        </div>
                      ) : (
                        /* Display Draft/Email content */
                        <div className="space-y-3">
                          {/* Subject */}
                          <p className="text-[12px] text-white/60">
                            <span className="text-white/25">Subject: </span>
                            <span className="font-semibold text-white/75">{data.subject}</span>
                          </p>

                          {/* Body */}
                          <pre className="text-[12px] text-white/55 leading-relaxed whitespace-pre-wrap font-sans"
                            style={{ maxHeight: "200px", overflowY: "auto" }}>
                            {data.body}
                          </pre>
                        </div>
                      )}
                    </div>
                  )
                })()}
              </>
            )}
          </div>

          {/* ── Activity Log ─────────────────────────────────────────────── */}
          {lead.activities && lead.activities.length > 0 && (
            <div className="mt-3 pt-3" style={{ borderTop: "1px solid rgba(255,255,255,.04)" }}>
              <p className="text-[9px] font-black uppercase tracking-widest text-white/20 mb-2">Activity</p>
              <div className="space-y-1.5">
                {lead.activities.map(act => {
                  const meta = ACTIVITY_META[act.type] ?? { icon: ActivityIcon, color: "text-white/30", label: act.type }
                  const Icon = meta.icon
                  return (
                    <div key={act.id} className="flex items-start gap-2">
                      <Icon className={`size-3 shrink-0 mt-0.5 ${meta.color}`} />
                      <div className="flex-1 min-w-0">
                        <p className="text-[11px] text-white/55 leading-snug">{act.note || meta.label}</p>
                        <p className="text-[9px] text-white/20 mt-0.5">
                          {new Date(act.createdAt).toLocaleString()}
                        </p>
                      </div>
                    </div>
                  )
                })}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

// ── Sequence tab ──────────────────────────────────────────────────────────────

function SequenceTab({ steps, leads }: { steps: SequenceStep[]; leads: Lead[] }) {
  const [activeStep, setActiveStep] = useState(steps[0]?.stepNumber ?? 1)
  const step = steps.find(s => s.stepNumber === activeStep) ?? steps[0]

  // Aggregate stats per step
  function statsForStep(stepNum: number) {
    const emails = leads.flatMap(l => l.emails.filter(e => e.stepNumber === stepNum))
    const sent     = emails.filter(e => !["FAILED", "BOUNCED", "DRAFT"].includes(e.status)).length
    const opened   = emails.filter(e => ["OPENED", "CLICKED", "REPLIED"].includes(e.status)).length
    const replied  = emails.filter(e => e.status === "REPLIED").length
    return { sent, opened, replied, total: emails.length }
  }

  if (steps.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-16 text-center gap-3">
        <p className="text-[13px] font-bold text-white/30">No sequence steps</p>
        <p className="text-[11px] text-white/20">Create a sequence to define your email cadence</p>
      </div>
    )
  }

  return (
    <div className="flex h-full min-h-0">
      {/* Step list (left) */}
      <div
        className="shrink-0 w-48 overflow-y-auto"
        style={{ borderRight: "1px solid rgba(255,255,255,.05)" }}
      >
        {steps.map(s => {
          const stats  = statsForStep(s.stepNumber)
          const isActive = activeStep === s.stepNumber
          return (
            <button
              key={s.stepNumber}
              onClick={() => setActiveStep(s.stepNumber)}
              className="w-full text-left px-4 py-3.5 transition-all"
              style={{
                background: isActive ? "rgba(255,255,255,.05)" : "transparent",
                borderBottom: "1px solid rgba(255,255,255,.04)",
                borderLeft: isActive ? "2px solid rgba(255,255,255,.35)" : "2px solid transparent",
              }}
            >
              <p className={`text-[12px] font-bold ${isActive ? "text-white/85" : "text-white/40"}`}>
                {STEP_DAY[s.stepNumber] ?? `Step ${s.stepNumber}`}
              </p>
              <p className="text-[10px] text-white/25 mt-0.5">
                {s.delayDays === 0 ? "Sends immediately" : `After ${s.delayDays} day${s.delayDays !== 1 ? "s" : ""}`}
              </p>
              {stats.sent > 0 && (
                <p className="text-[9px] text-white/20 mt-1">
                  {stats.sent} sent · {stats.opened} opened
                </p>
              )}
            </button>
          )
        })}
      </div>

      {/* Step detail (right) */}
      <div className="flex-1 overflow-y-auto px-6 py-5 space-y-5">
        {step ? (
          <>
            {/* Stats row */}
            {(() => {
              const stats = statsForStep(step.stepNumber)
              return stats.total > 0 ? (
                <div className="flex items-center gap-4 flex-wrap">
                  {[
                    { label: "Sent",    val: stats.sent,    color: "text-white/50" },
                    { label: "Opened",  val: stats.opened,  color: "text-emerald-400/70" },
                    { label: "Replied", val: stats.replied, color: "text-violet-400/70" },
                  ].map(({ label, val, color }) => (
                    <div key={label} className="flex items-center gap-1.5">
                      <span className={`text-[15px] font-black ${color}`}>{val}</span>
                      <span className="text-[11px] text-white/25">{label}</span>
                    </div>
                  ))}
                </div>
              ) : (
                <p className="text-[11px] text-white/20 italic">No emails sent at this step yet</p>
              )
            })()}

            {/* Template */}
            <div
              className="rounded-xl overflow-hidden"
              style={{ border: "1px solid rgba(255,255,255,.07)" }}
            >
              <div className="px-5 py-3" style={{ borderBottom: "1px solid rgba(255,255,255,.06)", background: "rgba(255,255,255,.02)" }}>
                <p className="text-[10px] font-black text-white/25 uppercase tracking-wide mb-1">Subject template</p>
                <p className="text-[13px] font-semibold text-white/75">
                  {step.subjectTemplate || <span className="text-white/25 italic">No subject template set</span>}
                </p>
              </div>
              <div className="px-5 py-4">
                <p className="text-[10px] font-black text-white/25 uppercase tracking-wide mb-2">Body template</p>
                <pre className="text-[12px] text-white/55 leading-relaxed whitespace-pre-wrap font-sans"
                  style={{ maxHeight: "320px", overflowY: "auto" }}>
                  {step.bodyTemplate || <span className="text-white/25 italic">No body template set</span>}
                </pre>
              </div>
            </div>

            <p className="text-[10px] text-white/20">
              Variables: <span className="text-white/35 font-mono">{"{{firstName}} {{company}} {{industry}} {{painPoint}}"}</span> are personalised per lead using AI
            </p>
          </>
        ) : (
          <p className="text-[12px] text-white/30">Select a step</p>
        )}
      </div>
    </div>
  )
}

// ── Main view with tabs ───────────────────────────────────────────────────────

export function CampaignView({ campaignId, status, autonomous, leads, sequenceSteps, onLeadsChange }: CampaignViewProps) {
  const [tab, setTab] = useState<"leads" | "sequence" | "activity">("leads")
  const [localLeads, setLocalLeads] = useState<Lead[]>(leads)
  const [queuingAll, setQueuingAll] = useState(false)
  const [generatingAllDrafts, setGeneratingAllDrafts] = useState(false)
  const [processingQueue, setProcessingQueue] = useState(false)
  const [campaignActivities, setCampaignActivities] = useState<ActivityRecord[]>([])

  function updateLeads(next: Lead[]) {
    setLocalLeads(next)
    onLeadsChange?.(next)
  }

  // Keep local state in sync if prop changes
  useEffect(() => {
    Promise.resolve().then(() => setLocalLeads(leads))
  }, [leads])

  const fetchActivities = useCallback(async () => {
    try {
      const res = await fetch(`/api/campaigns/${campaignId}/activities`)
      if (res.ok) setCampaignActivities(await res.json())
    } catch { /* silent */ }
  }, [campaignId])

  // Fetch activities when activity tab open
  useEffect(() => {
    if (tab !== "activity") return
    fetchActivities()
    const iv = setInterval(fetchActivities, 8000)
    return () => clearInterval(iv)
  }, [tab, fetchActivities])

  const hasEnriching = localLeads.some(l => l.status === "NEW" && !l.contactsJson)
  const draftCount = localLeads.reduce((n, l) => n + l.emails.filter(e => e.status === "DRAFT").length, 0)
  const pendingSendCount = localLeads.reduce((n, l) => n + l.emails.filter(e => ["QUEUED", "SENDING"].includes(e.status)).length, 0)
  const failedCount = localLeads.reduce((n, l) => n + l.emails.filter(e => e.status === "FAILED").length, 0)
  const workflowPhase = computeWorkflowPhase(status, autonomous, localLeads, generatingAllDrafts)

  async function refreshLeads() {
    const res = await fetch(`/api/campaigns/${campaignId}`)
    if (!res.ok) return
    const campaign = await res.json()
    const updatedLeads = campaign?.campaignLeads?.map((cl: { lead: Lead }) => cl.lead)
    if (Array.isArray(updatedLeads)) updateLeads(updatedLeads)
  }

  const leadsWithoutDrafts = localLeads.filter(l =>
    l.emails.length === 0 && !(["REPLIED","MEETING_BOOKED","NOT_INTERESTED","BOUNCED"].includes(l.status))
  )

  const TABS = [
    { id: "leads"    as const, label: `Leads (${localLeads.length})` },
    { id: "sequence" as const, label: `Sequence (${sequenceSteps.length} steps)` },
    { id: "activity" as const, label: "Activity Log" },
  ]

  async function handleGenerateAllDrafts() {
    setGeneratingAllDrafts(true)
    try {
      const res = await fetch(`/api/campaigns/${campaignId}/generate-drafts-all`, { method: "POST" })
      if (res.ok) {
        const data = await res.json()
        toast.success((data as { message?: string }).message || "Generating drafts in the background…")
      } else {
        const err = await res.json().catch(() => ({}))
        toast.error((err as { error?: string }).error || "Failed to start draft generation")
      }
    } catch {
      toast.error("An error occurred")
    } finally {
      setGeneratingAllDrafts(false)
    }
  }

  async function handleQueueAll() {
    setQueuingAll(true)
    try {
      const res = await fetch(`/api/campaigns/${campaignId}/queue-all`, { method: "POST" })
      if (res.ok) {
        toast.success("Sending approved drafts…")
        await refreshLeads()
      } else {
        toast.error("Failed to send drafts")
      }
    } catch {
      toast.error("An error occurred")
    } finally {
      setQueuingAll(false)
    }
  }

  async function handleProcessQueue() {
    setProcessingQueue(true)
    try {
      const res = await fetch("/api/process-queue", { method: "POST" })
      if (res.ok) {
        await refreshLeads()
      } else {
        toast.error("Failed to retry sends")
      }
    } catch {
      toast.error("An error occurred")
    } finally {
      setProcessingQueue(false)
    }
  }

  function handleUpdateLead(updated: Lead) {
    updateLeads(localLeads.map(l => l.id === updated.id ? updated : l))
  }

  return (
    <div className="flex flex-col h-full min-h-0">
      {/* Tab bar + add leads button */}
      <div
        className="shrink-0 flex items-center justify-between px-6 py-0"
        style={{ borderBottom: "1px solid rgba(255,255,255,.05)" }}
      >
        <div className="flex gap-0">
          {TABS.map(t => (
            <button
              key={t.id}
              onClick={() => setTab(t.id)}
              className="px-4 py-3 text-[12px] font-bold transition-all"
              style={{
                color: tab === t.id ? "rgba(255,255,255,.85)" : "rgba(255,255,255,.3)",
                borderBottom: tab === t.id ? "2px solid rgba(255,255,255,.5)" : "2px solid transparent",
              }}
            >
              {t.label}
            </button>
          ))}
        </div>

        {/* Add leads — only on leads tab */}
        {tab === "leads" && (
          <div className="flex items-center gap-2 py-2">
            <Link
              href="/leads/upload"
              className="flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-[11px] font-bold text-white/40 hover:text-white/65 transition-colors"
              style={{ background: "rgba(255,255,255,.04)", border: "1px solid rgba(255,255,255,.07)" }}
            >
              <Upload className="size-3" /> CSV
            </Link>
            <Link
              href="/leads/find"
              className="flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-[11px] font-bold text-white/40 hover:text-white/65 transition-colors"
              style={{ background: "rgba(255,255,255,.04)", border: "1px solid rgba(255,255,255,.07)" }}
            >
              <MapPin className="size-3" /> Maps
            </Link>
          </div>
        )}
      </div>

      {/* Tab content */}
      <div className="flex-1 min-h-0 overflow-y-auto">
        {tab === "leads" ? (
          localLeads.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-20 text-center gap-4">
              <div className="flex size-14 items-center justify-center rounded-2xl"
                style={{ background: "rgba(255,255,255,.03)", border: "1px solid rgba(255,255,255,.07)" }}>
                <Users className="size-6 text-white/20" />
              </div>
              <div>
                <p className="text-[14px] font-bold text-white/30">No leads enrolled</p>
                <p className="text-[12px] text-white/20 mt-1">Add leads to get started</p>
              </div>
              <div className="flex gap-2">
                <Link href="/leads/find"
                  className="inline-flex items-center gap-2 rounded-xl px-4 py-2 text-[12px] font-bold transition-all hover:brightness-110 font-sans"
                  style={{ background: "linear-gradient(135deg,#e2e5ed,#c8cdd8)", color: "#0f172a" }}>
                  <MapPin className="size-3.5" /> Find Leads
                </Link>
                <Link href="/leads/upload"
                  className="inline-flex items-center gap-2 rounded-xl px-4 py-2 text-[12px] font-bold text-white/50 hover:text-white/70 transition-all font-sans"
                  style={{ border: "1px solid rgba(255,255,255,.1)" }}>
                  <Upload className="size-3.5" /> Upload CSV
                </Link>
              </div>
            </div>
          ) : (
            <div>
              <CampaignWorkflowBar
                phase={workflowPhase}
                autonomous={autonomous}
                leadsWithoutDrafts={leadsWithoutDrafts.length}
                draftCount={draftCount}
                pendingSendCount={pendingSendCount}
                failedCount={failedCount}
                isGenerating={generatingAllDrafts}
                isSending={queuingAll || processingQueue || pendingSendCount > 0}
                onApproveAll={handleQueueAll}
                onRetryFailed={handleProcessQueue}
              />

              {/* Column headers */}
              <div
                className="hidden sm:grid items-center gap-3 px-5 py-2"
                style={{
                  gridTemplateColumns: "minmax(0,2fr) minmax(0,2fr) minmax(0,1.2fr) 52px 96px 28px",
                  borderBottom: "1px solid rgba(255,255,255,.04)",
                }}
              >
                {["Name", "Email", "Company", "Steps", "Status", ""].map(h => (
                  <p key={h} className="text-[9px] font-black text-white/20 uppercase tracking-widest">{h}</p>
                ))}
              </div>

              {localLeads.map((lead, i) => (
                <LeadRow
                  key={lead.id}
                  lead={lead}
                  sequenceSteps={sequenceSteps}
                  campaignId={campaignId}
                  isLast={i === localLeads.length - 1}
                  onUpdateLead={handleUpdateLead}
                />
              ))}
            </div>
          )
        ) : tab === "sequence" ? (
          <SequenceTab steps={sequenceSteps} leads={localLeads} />
        ) : (
          /* Activity Log tab */
          campaignActivities.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-20 text-center gap-3">
              <div className="size-12 rounded-2xl flex items-center justify-center"
                style={{ background: "rgba(255,255,255,.03)", border: "1px solid rgba(255,255,255,.07)" }}>
                <ActivityIcon className="size-5 text-white/20" />
              </div>
              <p className="text-[13px] font-bold text-white/25">No activity yet</p>
              <p className="text-[11px] text-white/15">Events will appear here as emails are sent</p>
            </div>
          ) : (
            <div className="px-5 py-4 space-y-0">
              {campaignActivities.map((act) => {
                const meta = ACTIVITY_META[act.type] ?? { icon: ActivityIcon, color: "text-white/30", label: act.type }
                const Icon = meta.icon
                const lead = act.lead
                const leadName = lead?.firstName
                  ? `${lead.firstName}${lead.lastName ? " " + lead.lastName : ""}`
                  : (lead?.email ?? "Unknown")
                return (
                  <div key={act.id} className="flex items-start gap-3 py-2.5" style={{ borderBottom: "1px solid rgba(255,255,255,.03)" }}>
                    <div className="size-7 rounded-xl flex items-center justify-center shrink-0 mt-0.5 bg-white/[.04] border border-white/[.06]">
                      <Icon className={`size-3.5 ${meta.color}`} />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-baseline gap-2 flex-wrap">
                        <span className="text-[12px] font-semibold text-white/70 truncate">{leadName}</span>
                        {lead?.company && <span className="text-[10px] text-white/25">{lead.company}</span>}
                      </div>
                      <p className="text-[11px] text-white/45 mt-0.5 leading-snug">{act.note || meta.label}</p>
                    </div>
                    <span className="text-[9px] text-white/20 shrink-0 mt-1">{new Date(act.createdAt).toLocaleString()}</span>
                  </div>
                )
              })}
            </div>
          )
        )}
      </div>
    </div>
  )
}

"use client"

import {
  Loader2, Sparkles, Send, FileText, Play, Zap,
  CheckCircle2, Pause, Users, AlertCircle,
} from "lucide-react"
import { computeWorkflowPhase, WORKFLOW_COPY, type WorkflowPhase } from "@/lib/campaign-workflow"

interface CampaignWorkflowBarProps {
  phase: WorkflowPhase
  autonomous: boolean
  leadsWithoutDrafts: number
  draftCount: number
  pendingSendCount: number
  failedCount: number
  isGenerating: boolean
  isSending: boolean
  onApproveAll?: () => void
  onRetryFailed?: () => void
}

const PHASE_STYLE: Record<WorkflowPhase, { gradient: string; border: string; icon: typeof Zap; iconColor: string; titleColor: string }> = {
  "no-leads":    { gradient: "rgba(255,255,255,.03)", border: "rgba(255,255,255,.08)", icon: Users, iconColor: "text-white/30", titleColor: "text-white/40" },
  enriching:     { gradient: "rgba(52,211,153,.06)", border: "rgba(52,211,153,.15)", icon: Loader2, iconColor: "text-emerald-400 animate-spin", titleColor: "text-emerald-300" },
  ready:         { gradient: "rgba(125,211,252,.06)", border: "rgba(125,211,252,.15)", icon: Play, iconColor: "text-sky-400", titleColor: "text-sky-300" },
  generating:    { gradient: "rgba(139,92,246,.07)", border: "rgba(139,92,246,.18)", icon: Sparkles, iconColor: "text-violet-400", titleColor: "text-violet-300" },
  sending:       { gradient: "rgba(125,211,252,.07)", border: "rgba(125,211,252,.18)", icon: Send, iconColor: "text-sky-400", titleColor: "text-sky-300" },
  review:        { gradient: "rgba(251,191,36,.06)", border: "rgba(251,191,36,.12)", icon: FileText, iconColor: "text-amber-400", titleColor: "text-amber-300" },
  live:          { gradient: "rgba(52,211,153,.06)", border: "rgba(52,211,153,.15)", icon: CheckCircle2, iconColor: "text-emerald-400", titleColor: "text-emerald-300" },
  paused:        { gradient: "rgba(251,191,36,.05)", border: "rgba(251,191,36,.12)", icon: Pause, iconColor: "text-amber-400", titleColor: "text-amber-300" },
}

export function CampaignWorkflowBar({
  phase, autonomous, leadsWithoutDrafts, draftCount, pendingSendCount, failedCount,
  isGenerating, isSending, onApproveAll, onRetryFailed,
}: CampaignWorkflowBarProps) {
  if (phase === "no-leads" || phase === "live") return null

  const style = PHASE_STYLE[phase]
  const Icon = style.icon
  const copy = WORKFLOW_COPY[phase]

  let title = copy.title
  let description = copy.description

  if (phase === "generating" && leadsWithoutDrafts > 0) {
    title = `Writing emails for ${leadsWithoutDrafts} lead${leadsWithoutDrafts !== 1 ? "s" : ""}`
    description = autonomous
      ? "Autopilot is on — emails send automatically as they're ready."
      : "Drafts will appear below as they're generated."
  }
  if (phase === "sending" && pendingSendCount > 0) {
    title = `Sending ${pendingSendCount} email${pendingSendCount !== 1 ? "s" : ""}`
  }
  if (phase === "review" && draftCount > 0) {
    title = `${draftCount} draft${draftCount !== 1 ? "s" : ""} ready for review`
  }
  if (phase === "enriching") {
    description = "Launch is available once enrichment completes."
  }

  const showApprove = phase === "review" && !autonomous && onApproveAll
  const showRetry = failedCount > 0 && onRetryFailed && !autonomous

  return (
    <div
      className="mx-5 my-4 p-4 rounded-2xl flex items-center justify-between gap-4 flex-wrap"
      style={{
        background: `linear-gradient(135deg, ${style.gradient}, transparent)`,
        border: `1px solid ${style.border}`,
      }}
    >
      <div className="flex items-start gap-2.5 min-w-0">
        <div
          className="size-8 rounded-xl flex items-center justify-center shrink-0 mt-0.5"
          style={{ background: "rgba(255,255,255,.04)", border: `1px solid ${style.border}` }}
        >
          {(phase === "generating" && isGenerating) || (phase === "sending" && isSending) ? (
            <Loader2 className={`size-4 ${style.iconColor}`} />
          ) : (
            <Icon className={`size-4 ${style.iconColor}`} />
          )}
        </div>
        <div className="min-w-0">
          <div className="flex items-center gap-2 flex-wrap">
            <h3 className={`text-[13px] font-bold ${style.titleColor}`}>{title}</h3>
            {autonomous && phase !== "paused" && (
              <span className="inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[9px] font-black uppercase tracking-wider text-emerald-400/80"
                style={{ background: "rgba(52,211,153,.1)", border: "1px solid rgba(52,211,153,.2)" }}>
                <Zap className="size-2.5 fill-current" /> Autopilot
              </span>
            )}
          </div>
          <p className="text-[11px] text-white/40 mt-0.5 leading-snug">{description}</p>
        </div>
      </div>

      <div className="flex items-center gap-2 shrink-0">
        {showRetry && (
          <button
            onClick={onRetryFailed}
            className="flex items-center gap-1.5 rounded-xl px-3 py-2 text-[11px] font-bold text-amber-300 transition-all hover:brightness-110"
            style={{ background: "rgba(251,191,36,.1)", border: "1px solid rgba(251,191,36,.2)" }}
          >
            <AlertCircle className="size-3.5" />
            Retry Failed
          </button>
        )}
        {showApprove && (
          <button
            onClick={onApproveAll}
            disabled={isSending}
            className="flex items-center gap-1.5 rounded-xl px-4 py-2 text-[12px] font-bold text-black bg-amber-400 hover:brightness-110 disabled:opacity-40 transition-all font-sans"
            style={{ boxShadow: "0 2px 10px rgba(251,191,36,.15)" }}
          >
            {isSending ? <Loader2 className="size-3.5 animate-spin" /> : <Play className="size-3.5 fill-current" />}
            {isSending ? "Sending…" : "Approve & Send All"}
          </button>
        )}
      </div>
    </div>
  )
}

"use client"

import { useEffect, useState, useRef } from "react"
import { useRouter } from "next/navigation"
import { Search, Compass, Database, Sparkles, Settings, ArrowRight, X, Command } from "lucide-react"
import { toast } from "sonner"

export function CommandPalette() {
  const [open, setOpen] = useState(false)
  const [search, setSearch] = useState("")
  const [selectedIndex, setSelectedIndex] = useState(0)
  const router = useRouter()
  const containerRef = useRef<HTMLDivElement>(null)

  // Listen for Ctrl+K / Cmd+K
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === "k") {
        e.preventDefault()
        setOpen((prev) => !prev)
      }
      if (e.key === "Escape") {
        setOpen(false)
      }
    }
    window.addEventListener("keydown", handleKeyDown)
    return () => window.removeEventListener("keydown", handleKeyDown)
  }, [])

  // Auto-scroll selected item into view
  useEffect(() => {
    if (!open) return
    const activeItem = containerRef.current?.querySelector("[data-active='true']")
    if (activeItem) {
      activeItem.scrollIntoView({ block: "nearest" })
    }
  }, [selectedIndex, open])

  // Define commands
  const commands = [
    {
      id: "dash",
      title: "Go to Dashboard",
      description: "View agency analytics & pipeline overview",
      category: "Navigation",
      icon: Compass,
      action: () => { router.push("/dashboard"); setOpen(false) }
    },
    {
      id: "leads",
      title: "Go to Leads Database",
      description: "Browse acquired leads and prospects",
      category: "Navigation",
      icon: Database,
      action: () => { router.push("/leads"); setOpen(false) }
    },
    {
      id: "campaigns",
      title: "Go to Campaigns",
      description: "Manage outreach campaigns and workflow stages",
      category: "Navigation",
      icon: Search,
      action: () => { router.push("/campaigns"); setOpen(false) }
    },
    {
      id: "settings",
      title: "Go to Settings",
      description: "Manage agency profile and autopilots",
      category: "Navigation",
      icon: Settings,
      action: () => { router.push("/settings/agency"); setOpen(false) }
    },
    {
      id: "advisor",
      title: "Ask Agnel AI Advisor",
      description: "Focus the Agnel chat bubble directly",
      category: "Quick Actions",
      icon: Sparkles,
      action: () => {
        const chatInput = document.querySelector("#ai-advisor-input") as HTMLInputElement
        if (chatInput) {
          chatInput.focus()
          toast.success("AI advisor chat focused!")
        } else {
          toast.info("Agnel chat is ready on the bottom right.")
        }
        setOpen(false)
      }
    }
  ]

  // Filter commands
  const filtered = commands.filter((c) =>
    c.title.toLowerCase().includes(search.toLowerCase()) ||
    c.description.toLowerCase().includes(search.toLowerCase())
  )

  // Reset index when search changes
  useEffect(() => {
    setSelectedIndex(0)
  }, [search])

  // Handle arrows + enter key
  useEffect(() => {
    if (!open) return
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "ArrowDown") {
        e.preventDefault()
        setSelectedIndex((prev) => (prev + 1) % filtered.length)
      } else if (e.key === "ArrowUp") {
        e.preventDefault()
        setSelectedIndex((prev) => (prev - 1 + filtered.length) % filtered.length)
      } else if (e.key === "Enter") {
        e.preventDefault()
        if (filtered[selectedIndex]) {
          filtered[selectedIndex].action()
        }
      }
    }
    window.addEventListener("keydown", handleKeyDown)
    return () => window.removeEventListener("keydown", handleKeyDown)
  }, [open, selectedIndex, filtered])

  if (!open) return null

  return (
    <div className="fixed inset-0 z-[100] flex items-start justify-center pt-[15vh] px-4">
      {/* Backdrop */}
      <div 
        className="fixed inset-0 bg-black/60 backdrop-blur-[6px]"
        onClick={() => setOpen(false)}
      />

      {/* Palette Container */}
      <div
        ref={containerRef}
        className="relative w-full max-w-lg overflow-hidden rounded-2xl border border-white/[0.08] shadow-2xl animate-in fade-in zoom-in-95 duration-150"
        style={{
          background: "rgba(20, 22, 28, 0.98)",
          boxShadow: "0 0 50px -12px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,.05)",
        }}
      >
        {/* Search header */}
        <div className="flex items-center gap-3 border-b border-white/[0.06] px-4 py-3.5">
          <Search className="size-4 text-white/30 shrink-0" />
          <input
            type="text"
            placeholder="Type a command or action..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="flex-1 bg-transparent text-[13px] text-white outline-none placeholder:text-white/20"
            autoFocus
          />
          <button 
            onClick={() => setOpen(false)}
            className="rounded p-0.5 text-white/25 hover:text-white/50 hover:bg-white/5 transition-colors"
          >
            <X className="size-3.5" />
          </button>
        </div>

        {/* List items */}
        <div className="max-h-[320px] overflow-y-auto p-1.5 space-y-0.5">
          {filtered.length === 0 ? (
            <p className="px-3 py-6 text-center text-[11px] text-white/20">No matching commands found.</p>
          ) : (
            filtered.map((item, idx) => {
              const active = idx === selectedIndex
              const Icon = item.icon

              return (
                <button
                  key={item.id}
                  data-active={active}
                  onClick={item.action}
                  className={`w-full flex items-center justify-between rounded-xl px-3 py-2.5 text-left transition-all ${
                    active
                      ? "text-white bg-white/[0.05]"
                      : "text-white/50 hover:bg-white/[0.02]"
                  }`}
                  style={active ? {
                    border: "1px solid rgba(255,255,255,.06)",
                    boxShadow: "inset 0 1px 0 rgba(255,255,255,.03)",
                  } : {
                    border: "1px solid transparent"
                  }}
                >
                  <div className="flex items-center gap-3 min-w-0">
                    <div 
                      className={`flex size-8 shrink-0 items-center justify-center rounded-lg border transition-colors ${
                        active 
                          ? "border-violet-500/20 bg-violet-500/10 text-violet-400" 
                          : "border-white/5 bg-white/5 text-white/30"
                      }`}
                    >
                      <Icon className="size-4" />
                    </div>
                    <div className="min-w-0">
                      <p className="text-[12.5px] font-bold tracking-tight">{item.title}</p>
                      <p className="text-[10px] text-white/30 mt-0.5 truncate">{item.description}</p>
                    </div>
                  </div>

                  {active && (
                    <div className="flex items-center gap-1 text-[10px] font-bold text-violet-400 shrink-0">
                      <span>Execute</span>
                      <ArrowRight className="size-3" />
                    </div>
                  )}
                </button>
              )
            })
          )}
        </div>

        {/* Footer shortcuts */}
        <div className="flex items-center justify-between border-t border-white/[0.06] bg-black/20 px-4 py-2 text-[10px] text-white/20 select-none">
          <div className="flex items-center gap-3">
            <span className="flex items-center gap-1">
              <kbd className="rounded border border-white/10 bg-white/5 px-1 py-0.25 font-mono text-[9px]">Esc</kbd> Close
            </span>
            <span className="flex items-center gap-1">
              <kbd className="rounded border border-white/10 bg-white/5 px-1 py-0.25 font-mono text-[9px]">↑↓</kbd> Navigate
            </span>
            <span className="flex items-center gap-1">
              <kbd className="rounded border border-white/10 bg-white/5 px-1 py-0.25 font-mono text-[9px]">Enter</kbd> Trigger
            </span>
          </div>
          <div className="flex items-center gap-1 font-semibold">
            <Command className="size-3 text-white/35" />
            <span>Command Menu</span>
          </div>
        </div>
      </div>
    </div>
  )
}

"use client"

import { useState, useEffect } from "react"
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Check, ArrowUpRight, GitBranch, Search, Megaphone } from "lucide-react"
import Link from "next/link"

const ICON_MAP: Record<string, any> = {
  GitBranch,
  Search,
  Megaphone,
}

type Step = {
  key: string
  label: string
  desc: string
  href: string
  cta: string
  icon: string
  done: boolean
}

interface GettingStartedModalProps {
  steps: Step[]
}

export function GettingStartedModal({ steps }: GettingStartedModalProps) {
  const [open, setOpen] = useState(false)
  const [dismissed, setDismissed] = useState(true)

  const doneCount = steps.filter((s) => s.done).length
  const allDone = doneCount === steps.length

  useEffect(() => {
    // Check if dismissed in local storage
    const isDismissed = localStorage.getItem("getting-started-dismissed") === "true"
    setDismissed(isDismissed)

    // Automatically open if there are pending steps and not previously dismissed
    if (!allDone && !isDismissed) {
      setOpen(true)
    }
  }, [allDone])

  function handleOpenChange(newOpen: boolean) {
    setOpen(newOpen)
    if (!newOpen) {
      // Mark as dismissed when closed
      localStorage.setItem("getting-started-dismissed", "true")
      setDismissed(true)
    }
  }

  return (
    <>
      {/* Manual trigger if dismissed but not all done */}
      {!allDone && dismissed && (
        <button
          onClick={() => setOpen(true)}
          className="inline-flex items-center gap-2 rounded-xl px-4 py-2.5 text-[12.5px] font-bold text-white/70 hover:text-white transition-all hover:scale-[1.02] active:scale-[0.98] border border-white/[0.08]"
          style={{ background: "rgba(167,139,250,.1)" }}
        >
          <span className="flex size-5 items-center justify-center rounded-md bg-violet-500/20 text-violet-400">
            {steps.length - doneCount}
          </span>
          Setup pending
        </button>
      )}

      <Dialog open={open} onOpenChange={handleOpenChange}>
        <DialogContent className="sm:max-w-[700px] bg-[#1a1c24] border-white/[0.08] p-0 overflow-hidden">
          <div
            className="p-6 md:p-8"
            style={{
              background: "linear-gradient(145deg,rgba(167,139,250,.05) 0%,rgba(255,255,255,.01) 100%)",
            }}
          >
            <DialogHeader className="mb-6">
              <DialogTitle className="text-xl font-black text-white/90 flex items-center justify-between">
                Getting started
                <span className="text-[12px] font-bold text-white/40 font-normal mt-0.5">
                  {doneCount} of {steps.length} steps complete
                </span>
              </DialogTitle>
            </DialogHeader>

            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              {steps.map((step, idx) => {
                const Icon = ICON_MAP[step.icon] || Check
                return (
                  <Link
                    key={step.key}
                    href={step.href}
                    onClick={() => handleOpenChange(false)}
                    className="group relative flex flex-col gap-3 rounded-xl p-5 transition-all hover:-translate-y-1"
                    style={{
                      background: step.done ? "rgba(52,211,153,.04)" : "rgba(255,255,255,.025)",
                      border: step.done ? "1px solid rgba(52,211,153,.18)" : "1px solid rgba(255,255,255,.06)",
                    }}
                  >
                    <div className="flex items-center justify-between">
                      <div
                        className="flex size-10 items-center justify-center rounded-xl"
                        style={{
                          background: step.done ? "rgba(52,211,153,.12)" : "rgba(167,139,250,.1)",
                          border: step.done ? "1px solid rgba(52,211,153,.25)" : "1px solid rgba(167,139,250,.18)",
                        }}
                      >
                        {step.done ? <Check className="size-5 text-emerald-400" /> : <Icon className="size-5 text-violet-300" />}
                      </div>
                      <span className="text-[11px] font-black text-white/15">{idx + 1}</span>
                    </div>
                    <div>
                      <p className="text-[13px] font-bold text-white/80">{step.label}</p>
                      <p className="text-[12px] text-white/30 mt-1 leading-relaxed">{step.desc}</p>
                    </div>
                    <div
                      className="mt-auto flex items-center gap-1.5 text-[12px] font-bold transition-colors pt-2"
                      style={{ color: step.done ? "rgba(52,211,153,.7)" : "rgba(167,139,250,.7)" }}
                    >
                      {step.done ? "Done — view" : step.cta}
                      <ArrowUpRight className="size-3.5 group-hover:translate-x-0.5 transition-transform" />
                    </div>
                  </Link>
                )
              })}
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </>
  )
}

"use client"

import { useState, useRef } from "react"
import {
  MapPin, Globe2, Gauge, Shield, Sparkles, Zap,
  ExternalLink, X, Check, Plus, Loader2,
  ChevronLeft, ChevronRight, UserSearch, Star,
  Copy, Phone, Mail, BarChart3,
} from "lucide-react"
import { useEffect } from "react"
import { toast } from "sonner"
import type { ContactResult } from "@/lib/contact-finder"

export type Place = {
  id: string
  displayName: { text: string }
  formattedAddress: string
  websiteUri?: string
  nationalPhoneNumber?: string
  rating?: number
  userRatingCount?: number
  businessStatus?: string
  primaryType?: string
  editorialSummary?: { text: string }
  photos?: { name: string }[]
  reviews?: {
    text: { text: string }
    rating: number
    authorAttribution: { displayName: string }
  }[]
  cachedContacts?: unknown[]
  cachedProfiles?: unknown[]
}

interface LeadAnalysisPanelProps {
  place: Place | null
  onClose: () => void
  isSelected: boolean
  onToggle: (id: string) => void
  emailFromPlace: (p: Place) => string
  searchTarget?: "b2b" | "b2c"
}

type Tab = "overview" | "contact" | "audit" | "ai"

const TABS: { id: Tab; label: string }[] = [
  { id: "overview", label: "Overview" },
  { id: "contact",  label: "Contact"  },
  { id: "audit",    label: "Audit"    },
  { id: "ai",       label: "AI"       },
]

const PEEK_H = 128

export function LeadAnalysisPanel({
  place: placeProp,
  onClose,
  isSelected,
  onToggle,
  searchTarget = "b2b",
}: LeadAnalysisPanelProps) {
  const [expanded, setExpanded]               = useState(false)
  const [activeTab, setActiveTab]             = useState<Tab>("overview")
  const [activePhoto, setActivePhoto]         = useState(0)
  const [isClosing, setIsClosing]             = useState(false)

  // drag-to-expand
  const dragStartY  = useRef(0)
  const dragging    = useRef(false)

  // enrichment
  const [socials, setSocials]                         = useState<string[]>([])
  const [discoveredEmails, setDiscoveredEmails]       = useState<string[]>([])
  const [loadingEnrich, setLoadingEnrich]             = useState(false)
  const [enrichSearched, setEnrichSearched]           = useState(false)

  // decision maker
  const [contacts, setContacts]                       = useState<ContactResult[]>([])
  const [searchingContacts, setSearchingContacts]     = useState(false)
  const [contactsSearched, setContactsSearched]       = useState(false)

  // audit
  const [auditData, setAuditData] = useState<{
    ssl: boolean; speed: number; mobile: boolean; pixel: boolean
  } | null>(null)
  const [auditing, setAuditing] = useState(false)

  // icebreaker
  const [icebreaker, setIcebreaker]       = useState("")
  const [generatingIce, setGeneratingIce] = useState(false)

  useEffect(() => {
    setTimeout(() => {
      setExpanded(false)
      setActiveTab("overview")
      setActivePhoto(0)
      setIsClosing(false)
      setSocials([])
      setDiscoveredEmails([])
      setLoadingEnrich(false)
      setEnrichSearched(false)
      setContacts([])
      setSearchingContacts(false)
      setContactsSearched(false)
      setAuditData(null)
      setAuditing(false)
      setIcebreaker("")
      setGeneratingIce(false)
    }, 0)
    if (placeProp?.websiteUri) {
      runEnrichment()
      runAudit()
      findDecisionMaker()
    }
  }, [placeProp?.id])

  if (!placeProp) return null
  const place = placeProp

  const initiateClose = () => {
    setIsClosing(true)
    setTimeout(onClose, 300)
  }

  // ── Drag handlers ────────────────────────────────────────────
  const onHandleDown = (e: React.PointerEvent) => {
    dragStartY.current = e.clientY
    dragging.current   = true
    ;(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId)
  }
  const onHandleUp = (e: React.PointerEvent) => {
    if (!dragging.current) return
    dragging.current = false
    const delta = dragStartY.current - e.clientY // positive = swipe up
    if (delta > 40)       setExpanded(true)
    else if (delta < -40) setExpanded(false)
    else                  setExpanded(p => !p) // tap = toggle
  }

  // ── Data functions ───────────────────────────────────────────
  async function runEnrichment() {
    if (!place?.websiteUri) return
    setLoadingEnrich(true)
    setEnrichSearched(true)
    try {
      const res = await fetch("/api/leads/enrich", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url: place.websiteUri }),
      })
      if (!res.ok) throw new Error()
      const data = await res.json()
      setDiscoveredEmails(data.emails ?? [])
      setSocials(data.socials ?? [])
    } catch { /* silent */ }
    finally  { setLoadingEnrich(false) }
  }

  async function runAudit() {
    if (!place?.websiteUri) return
    setAuditing(true)
    try {
      const res = await fetch("/api/leads/audit", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url: place.websiteUri }),
      })
      if (!res.ok) throw new Error()
      const data = await res.json()
      if (!data.error) setAuditData(data)
    } catch { /* silent */ }
    finally { setAuditing(false) }
  }

  async function generateIcebreaker() {
    setGeneratingIce(true)
    setIcebreaker("")
    try {
      const decisionMaker = contacts.find(c => c.isDecisionMaker)
      const res = await fetch("/api/leads/icebreaker", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          businessName: place.displayName.text,
          address: place.formattedAddress,
          industry: place.primaryType?.replace(/_/g, " ") ?? null,
          rating: place.rating ?? null,
          reviewCount: place.userRatingCount ?? null,
          auditData,
          decisionMakerFirstName: decisionMaker?.firstName ?? null,
        }),
      })
      if (!res.ok) throw new Error()
      const data = await res.json()
      setIcebreaker(data.icebreaker ?? "")
    } catch (err) {
      console.error("Icebreaker error:", err)
      toast.error("Failed to generate message — check console")
    } finally {
      setGeneratingIce(false)
    }
  }

  async function findDecisionMaker() {
    if (!place?.websiteUri) return
    setSearchingContacts(true)
    setContactsSearched(true)
    try {
      const res = await fetch("/api/leads/contact-search", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          websiteUrl: place.websiteUri,
          companyName: place.displayName.text,
          localNeighbors: searchTarget === "b2c",
        }),
      })
      if (!res.ok) throw new Error()
      const data = await res.json()
      setContacts(data.contacts ?? [])
    } catch {
      toast.error("Contact search failed")
    } finally {
      setSearchingContacts(false)
    }
  }

  // ── Shared sub-styles ────────────────────────────────────────
  const sectionHead = "text-[10px] font-black text-white/30 uppercase tracking-[.18em] mb-3"
  const card        = { background: "rgba(255,255,255,.03)", border: "1px solid rgba(255,255,255,.06)" }

  // ── Tab: Overview ────────────────────────────────────────────
  function renderOverviewTab() {
    return (
      <div className="space-y-6">
        {/* Photo slider */}
        {place.photos && place.photos.length > 0 && (
          <div className="relative h-52 rounded-2xl overflow-hidden group/slider select-none touch-none"
            style={{ border: "1px solid rgba(255,255,255,.07)" }}>
            <div className={`flex h-full ${dragging.current ? "" : "transition-transform duration-500 ease-out"}`}
              style={{ transform: `translateX(-${activePhoto * 100}%)` }}>
              {place.photos.map((photo, i) => (
                <img key={i} alt=""
                  src={`https://places.googleapis.com/v1/${photo.name}/media?maxHeightPx=500&maxWidthPx=900&key=${process.env.NEXT_PUBLIC_GOOGLE_MAPS_API_KEY}`}
                  className="w-full h-full object-cover shrink-0 pointer-events-none"
                />
              ))}
            </div>
            <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent" />
            {place.photos.length > 1 && (
              <>
                <button onClick={() => setActivePhoto(p => Math.max(0, p - 1))}
                  className="absolute left-3 top-1/2 -translate-y-1/2 size-8 rounded-full bg-black/30 backdrop-blur border border-white/10 flex items-center justify-center opacity-0 group-hover/slider:opacity-100 transition-opacity">
                  <ChevronLeft className="size-4 text-white" />
                </button>
                <button onClick={() => setActivePhoto(p => Math.min(place.photos!.length - 1, p + 1))}
                  className="absolute right-3 top-1/2 -translate-y-1/2 size-8 rounded-full bg-black/30 backdrop-blur border border-white/10 flex items-center justify-center opacity-0 group-hover/slider:opacity-100 transition-opacity">
                  <ChevronRight className="size-4 text-white" />
                </button>
                <div className="absolute bottom-3 inset-x-0 flex justify-center gap-1.5">
                  {place.photos.map((_, i) => (
                    <div key={i} className={`h-1 rounded-full transition-all ${i === activePhoto ? "w-5 bg-white" : "w-1 bg-white/30"}`} />
                  ))}
                </div>
              </>
            )}
          </div>
        )}

        {/* Stats row */}
        <div className="grid grid-cols-3 gap-3">
          {[
            { label: "Rating",  value: place.rating ? `${place.rating}★` : "—",             color: "text-amber-400" },
            { label: "Reviews", value: place.userRatingCount?.toLocaleString() ?? "—",       color: "text-sky-400"   },
            { label: "Status",  value: place.businessStatus === "OPERATIONAL" ? "Open" : (place.businessStatus ?? "—"), color: "text-emerald-400" },
          ].map(({ label, value, color }) => (
            <div key={label} className="rounded-xl p-3 text-center" style={card}>
              <p className={`text-[15px] font-black ${color}`}>{value}</p>
              <p className="text-[9px] text-white/30 mt-0.5 uppercase tracking-wide">{label}</p>
            </div>
          ))}
        </div>

        {/* Business summary */}
        {place.editorialSummary?.text && (
          <div className="rounded-xl p-4" style={card}>
            <p className="text-[12px] text-white/55 leading-relaxed italic">&quot;{place.editorialSummary.text}&quot;</p>
          </div>
        )}

        {/* Address + website */}
        <div className="space-y-2">
          <div className="flex items-start gap-3 py-2 border-b border-white/[.04]">
            <MapPin className="size-3.5 text-white/25 mt-0.5 shrink-0" />
            <span className="text-[12px] text-white/55 leading-snug">{place.formattedAddress}</span>
          </div>
          {place.websiteUri && (
            <div className="flex items-center gap-3 py-2 border-b border-white/[.04]">
              <Globe2 className="size-3.5 text-white/25 shrink-0" />
              <a href={place.websiteUri} target="_blank" rel="noopener noreferrer"
                className="text-[12px] text-sky-400 hover:text-sky-300 transition-colors truncate flex-1">
                {new URL(place.websiteUri).hostname}
              </a>
              <ExternalLink className="size-3 text-white/20 shrink-0" />
            </div>
          )}
          {place.nationalPhoneNumber && (
            <div className="flex items-center gap-3 py-2">
              <Phone className="size-3.5 text-white/25 shrink-0" />
              <span className="text-[12px] text-white/55">{place.nationalPhoneNumber}</span>
            </div>
          )}
        </div>

        {/* Top review */}
        {place.reviews && place.reviews[0] && (
          <div>
            <p className={sectionHead}>Top Review</p>
            <div className="rounded-xl p-4 space-y-2" style={card}>
              <div className="flex items-center justify-between">
                <span className="text-[11px] font-bold text-white/50">{place.reviews[0].authorAttribution.displayName}</span>
                <span className="text-[11px] text-amber-400 font-mono">{place.reviews[0].rating}★</span>
              </div>
              <p className="text-[12px] text-white/50 leading-relaxed line-clamp-3 italic">
                &quot;{place.reviews[0].text.text}&quot;
              </p>
            </div>
          </div>
        )}
      </div>
    )
  }

  // ── Tab: Contact ─────────────────────────────────────────────
  function renderContactTab() {
    return (
      <div className="space-y-6">
        {/* Decision Maker */}
        <div>
          <div className="flex items-center justify-between mb-3">
            <p className={sectionHead.replace("mb-3", "")}>Decision Maker</p>
            {contactsSearched && !searchingContacts && (
              <button onClick={findDecisionMaker}
                className="text-[10px] font-bold text-sky-400 hover:text-sky-300 flex items-center gap-1">
                <UserSearch className="size-3" /> Refresh
              </button>
            )}
          </div>

          {!place.websiteUri ? (
            <div className="rounded-xl p-4 text-center" style={card}>
              <p className="text-[11px] text-white/25">No website — can&apos;t search for contacts</p>
            </div>
          ) : (searchingContacts || !contactsSearched) ? (
            <div className="space-y-3">
              <div className="flex items-center gap-2 text-[10px] text-sky-400/50 uppercase tracking-widest px-1 font-bold">
                <Loader2 className="size-3 animate-spin text-sky-400" />
                <span>Scanning domain footprints...</span>
              </div>
              <div className="space-y-2.5 animate-pulse">
                <div className="rounded-xl p-3.5 border border-white/5 bg-white/[0.015] space-y-3">
                  <div className="flex items-center justify-between">
                    <div className="space-y-1.5 flex-1">
                      <div className="h-3.5 w-28 bg-white/10 rounded" />
                      <div className="h-2.5 w-16 bg-white/5 rounded" />
                    </div>
                    <div className="h-4 w-12 bg-white/5 rounded-full" />
                  </div>
                  <div className="h-3 w-44 bg-white/5 rounded" />
                  <div className="space-y-1 pt-1">
                    <div className="flex justify-between">
                      <div className="h-2 w-12 bg-white/5 rounded" />
                      <div className="h-2 w-8 bg-white/5 rounded" />
                    </div>
                    <div className="h-1 w-full bg-white/5 rounded-full" />
                  </div>
                </div>
              </div>
            </div>
          ) : contacts.length === 0 ? (
            <div className="rounded-xl p-4 text-center" style={card}>
              <p className="text-[11px] text-white/25">No decision maker identified</p>
            </div>
          ) : (
            <div className="space-y-2.5">
              {contacts.slice(0, 4).map((c, i) => {
                const barColor = c.confidence >= 75 ? "#34d399" : c.confidence >= 50 ? "#fbbf24" : "#f87171"
                const srcLabel = c.sources.includes("ai-extracted") ? "AI"
                  : c.sources.includes("format-matched") ? "Format"
                  : c.sources.includes("website-scraped") ? "Site" : "Gen"
                return (
                  <div key={i}
                    className="group/c relative rounded-xl p-3.5 transition-all hover:brightness-110"
                    style={{
                      background: c.isDecisionMaker
                        ? "linear-gradient(135deg,rgba(52,211,153,.06),rgba(255,255,255,.02))"
                        : "rgba(255,255,255,.025)",
                      border: c.isDecisionMaker
                        ? "1px solid rgba(52,211,153,.15)"
                        : "1px solid rgba(255,255,255,.05)",
                    }}>
                    <div className="flex items-start justify-between gap-2 mb-2">
                      <div className="min-w-0">
                        {c.name   && <p className="text-[12px] font-bold text-white/80 truncate">{c.name}</p>}
                        {c.title  && <p className="text-[10px] text-white/40 mt-0.5 truncate">{c.title}</p>}
                        {!c.name && !c.title && <p className="text-[10px] text-white/30 italic">Generic inbox</p>}
                      </div>
                      <div className="flex items-center gap-1 shrink-0">
                        {c.isDecisionMaker && (
                          <span className="flex items-center gap-1 px-1.5 py-0.5 rounded-full text-[8px] font-black uppercase text-emerald-400"
                            style={{ background: "rgba(52,211,153,.1)", border: "1px solid rgba(52,211,153,.2)" }}>
                            <Star className="size-2 fill-current" /> DM
                          </span>
                        )}
                        {c.gravatar && (
                          <span className="px-1.5 py-0.5 rounded-full text-[8px] font-black uppercase text-sky-400"
                            style={{ background: "rgba(56,189,248,.08)", border: "1px solid rgba(56,189,248,.15)" }}>
                            ✓ Live
                          </span>
                        )}
                      </div>
                    </div>
                    <div className="flex items-center gap-2 mb-2.5">
                      <span className="text-[11px] font-mono text-white/60 truncate flex-1">{c.email}</span>
                      <button
                        onClick={() => { navigator.clipboard.writeText(c.email); toast.success("Copied") }}
                        className="opacity-0 group-hover/c:opacity-100 transition-opacity shrink-0">
                        <Copy className="size-3 text-white/40 hover:text-white" />
                      </button>
                    </div>
                    <div className="space-y-1">
                      <div className="flex items-center justify-between">
                        <span className="text-[9px] font-bold text-white/20 uppercase tracking-wide">Confidence</span>
                        <div className="flex items-center gap-1.5">
                          <span className="px-1 py-0.5 rounded text-[8px] font-black uppercase"
                            style={{ background: "rgba(255,255,255,.04)", color: "rgba(255,255,255,.25)" }}>
                            {srcLabel}
                          </span>
                          <span className="text-[10px] font-black" style={{ color: barColor }}>{c.confidence}%</span>
                        </div>
                      </div>
                      <div className="h-1 w-full rounded-full" style={{ background: "rgba(255,255,255,.06)" }}>
                        <div className="h-full rounded-full transition-all duration-700"
                          style={{ width: `${c.confidence}%`, background: barColor, boxShadow: `0 0 6px ${barColor}55` }} />
                      </div>
                    </div>
                  </div>
                )
              })}
            </div>
          )}
        </div>

        {/* Found emails */}
        <div>
          <p className={sectionHead}>Scraped Emails</p>
          {(loadingEnrich || !enrichSearched) ? (
            <div className="space-y-2">
              {[1, 2].map(i => <div key={i} className="h-8 rounded-lg bg-white/[.04] animate-pulse" />)}
            </div>
          ) : discoveredEmails.length > 0 ? (
            <div className="space-y-1.5">
              {discoveredEmails.map((email, i) => (
                <div key={i} className="group/email flex items-center gap-3 rounded-lg px-3 py-2" style={card}>
                  <Mail className="size-3 text-white/25 shrink-0" />
                  <span className="text-[12px] font-mono text-white/60 truncate flex-1">{email}</span>
                  <button onClick={() => { navigator.clipboard.writeText(email); toast.success("Copied") }}
                    className="opacity-0 group-hover/email:opacity-100 transition-opacity">
                    <Copy className="size-3 text-white/40 hover:text-white" />
                  </button>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-[11px] text-white/25 italic">None found on site</p>
          )}
        </div>

        {/* Socials */}
        {(loadingEnrich || !enrichSearched) ? (
          <div>
            <p className={sectionHead}>Social</p>
            <div className="flex gap-2">
              <div className="h-7 w-20 bg-white/[.04] rounded-xl animate-pulse" />
              <div className="h-7 w-20 bg-white/[.04] rounded-xl animate-pulse" />
            </div>
          </div>
        ) : socials.length > 0 ? (
          <div>
            <p className={sectionHead}>Social</p>
            <div className="flex flex-wrap gap-2">
              {socials.map((link, i) => {
                const label = link.includes("facebook") ? "Facebook"
                  : link.includes("instagram") ? "Instagram"
                  : link.includes("linkedin")  ? "LinkedIn"
                  : link.includes("twitter") || link.includes("x.com") ? "X / Twitter"
                  : "Link"
                return (
                  <a key={i} href={link} target="_blank" rel="noopener noreferrer"
                    className="px-3 py-1.5 rounded-xl text-[11px] font-bold text-white/40 hover:text-white/70 transition-colors"
                    style={card}>
                    {label}
                  </a>
                )
              })}
            </div>
          </div>
        ) : null}
      </div>
    )
  }

  // ── Tab: Audit ───────────────────────────────────────────────
  function renderAuditTab() {
    return (
      <div className="space-y-6">
        {!place.websiteUri ? (
          <div className="rounded-xl p-5 text-center" style={card}>
            <Globe2 className="size-5 text-amber-400/50 mx-auto mb-2" />
            <p className="text-[12px] font-bold text-amber-400/70">No website to audit</p>
            <p className="text-[10px] text-white/25 mt-1">High-intent lead for web services</p>
          </div>
        ) : auditing ? (
          <div className="py-10 flex flex-col items-center gap-3">
            <Loader2 className="size-6 animate-spin text-sky-400" />
            <p className="text-[11px] text-white/30">Auditing {new URL(place.websiteUri).hostname}…</p>
          </div>
        ) : auditData ? (
          <>
            <div className="grid grid-cols-2 gap-3">
              {[
                { label: "SSL",    value: auditData.ssl    ? "Secure"    : "Insecure",  icon: Shield,  ok: auditData.ssl        },
                { label: "Speed",  value: `${auditData.speed}ms`,                       icon: Gauge,   ok: auditData.speed > 70 },
                { label: "Pixel",  value: auditData.pixel  ? "Active"    : "Missing",   icon: Sparkles,ok: auditData.pixel      },
                { label: "Mobile", value: auditData.mobile ? "Optimised" : "Poor",      icon: Zap,     ok: auditData.mobile     },
              ].map(({ label, value, icon: Icon, ok }) => (
                <div key={label} className="rounded-xl p-4 space-y-2" style={card}>
                  <div className="flex items-center gap-2">
                    <Icon className={`size-3.5 ${ok ? "text-emerald-400" : "text-red-400"}`} />
                    <span className="text-[9px] font-black text-white/30 uppercase tracking-widest">{label}</span>
                  </div>
                  <p className={`text-[13px] font-bold ${ok ? "text-white/80" : "text-red-400/80"}`}>{value}</p>
                </div>
              ))}
            </div>

            {/* Pain points */}
            <div>
              <p className={sectionHead}>AI Pain Points</p>
              <div className="rounded-xl p-4 space-y-3" style={card}>
                {!auditData.ssl && (
                  <PainPoint num={1} text={<><strong className="text-white">No SSL</strong> — Google downgrades ranking; visitors see a &apos;Not Secure&apos; warning.</>} />
                )}
                {auditData.speed < 70 && (
                  <PainPoint num={!auditData.ssl ? 2 : 1} text={<><strong className="text-white">Slow load ({auditData.speed}ms)</strong> — 50%+ of mobile users leave before the page finishes.</>} />
                )}
                {!auditData.pixel && (
                  <PainPoint num={[!auditData.ssl, auditData.speed < 70].filter(Boolean).length + 1}
                    text={<><strong className="text-white">No tracking pixel</strong> — ad spend is unattributed; no retargeting possible.</>} />
                )}
                {auditData.ssl && auditData.speed >= 70 && auditData.pixel && (
                  <PainPoint num={1} color="emerald" text="Strong technical foundation. Angle: scale existing traffic rather than fix leaks." />
                )}
              </div>
            </div>
          </>
        ) : (
          <div className="rounded-xl p-6 text-center" style={card}>
            <BarChart3 className="size-6 text-white/15 mx-auto mb-3" />
            <p className="text-[11px] text-white/25 mb-4">Check SSL, speed, pixel &amp; mobile in one click</p>
            <button onClick={runAudit}
              className="inline-flex items-center gap-2 px-5 py-2 rounded-xl text-[12px] font-bold text-black hover:brightness-110 transition-all"
              style={{ background: "linear-gradient(135deg,#e2e5ed,#c8cdd8)", boxShadow: "0 2px 8px rgba(0,0,0,.3)" }}>
              <Gauge className="size-3.5" /> Run Audit
            </button>
          </div>
        )}
      </div>
    )
  }

  // ── Tab: AI Writer ───────────────────────────────────────────
  function renderAITab() {
    return (
      <div className="space-y-4">
        <div className="relative rounded-2xl p-5 overflow-hidden"
          style={{
            background: "linear-gradient(145deg,rgba(52,211,153,.06),rgba(255,255,255,.02))",
            border: "1px solid rgba(52,211,153,.12)",
          }}>
          <div className="absolute inset-0 opacity-[.025] pointer-events-none"
            style={{ backgroundImage: "radial-gradient(#34d399 0.5px,transparent 0.5px)", backgroundSize: "16px 16px" }} />
          <div className="absolute top-4 right-4">
            <Sparkles className="size-4 text-emerald-400/25" />
          </div>

          {generatingIce ? (
            <div className="py-6 flex flex-col items-center gap-3">
              <Loader2 className="size-5 animate-spin text-emerald-400" />
              <p className="text-[11px] text-white/30 font-bold uppercase tracking-widest">Writing…</p>
            </div>
          ) : icebreaker ? (
            <div className="space-y-4">
              <p className="text-[13px] text-white/75 leading-relaxed italic">&quot;{icebreaker}&quot;</p>
              <div className="flex gap-2">
                <button
                  onClick={() => { navigator.clipboard.writeText(icebreaker); toast.success("Copied") }}
                  className="flex items-center gap-1.5 text-[10px] font-black uppercase text-emerald-400 hover:text-emerald-300 transition-colors">
                  <Copy className="size-3" /> Copy
                </button>
                <span className="text-white/10">·</span>
                <button
                  onClick={generateIcebreaker}
                  className="text-[10px] font-black uppercase text-white/30 hover:text-white/50 transition-colors">
                  Regenerate
                </button>
              </div>
            </div>
          ) : (
            <div className="text-center py-4">
              <p className="text-[11px] text-white/25 mb-5 max-w-[200px] mx-auto leading-normal italic">
                AI writes a personalised hook using this business&apos;s data
              </p>
              <button onClick={generateIcebreaker}
                className="inline-flex items-center gap-2 px-6 py-2.5 rounded-xl bg-emerald-400 text-black text-[12px] font-black hover:brightness-110 hover:scale-105 active:scale-95 transition-all"
                style={{ boxShadow: "0 0 20px rgba(52,211,153,.3)" }}>
                <Zap className="size-3.5 fill-current" /> Craft Message
              </button>
            </div>
          )}
        </div>
      </div>
    )
  }

  // ── Render ───────────────────────────────────────────────────
  return (
    <>
      {/* Backdrop (expanded only — constrained to content area) */}
      {expanded && (
        <div
          className={`fixed inset-y-0 right-0 z-[90] bg-black/50 backdrop-blur-[2px] transition-opacity duration-300 ${isClosing ? "opacity-0" : "opacity-100"}`}
          style={{ left: "var(--sidebar-w, 0px)" }}
          onClick={initiateClose}
        />
      )}

      {/* Sheet */}
      <div
        className={`fixed bottom-0 right-0 z-[100] flex flex-col transition-all duration-350 ease-out ${isClosing ? "translate-y-full" : "translate-y-0"}`}
        style={{
          left:         "var(--sidebar-w, 0px)",
          height:       expanded ? "80vh" : `${PEEK_H}px`,
          borderRadius: "20px 20px 0 0",
          background:   "rgba(18,20,26,.95)",
          borderTop:    "1px solid rgba(255,255,255,.08)",
          backdropFilter: "blur(20px)",
          boxShadow:    "0 -24px 80px rgba(0,0,0,.7)",
        }}
      >
        {/* Dot grid overlay */}
        <div className="absolute inset-0 pointer-events-none opacity-[.12] rounded-[20px_20px_0_0]"
          style={{ backgroundImage: "radial-gradient(rgba(255,255,255,.08) 1px,transparent 1px)", backgroundSize: "28px 28px" }} />

        {/* Top edge glow */}
        <div className="absolute top-0 inset-x-0 h-px"
          style={{ background: "linear-gradient(90deg,transparent,rgba(255,255,255,.12),transparent)" }} />

        {/* ── Drag handle ── */}
        <div
          className="flex justify-center pt-3 pb-1 cursor-grab active:cursor-grabbing select-none relative z-10 touch-none"
          onPointerDown={onHandleDown}
          onPointerUp={onHandleUp}
        >
          <div className="w-9 h-1 rounded-full bg-white/15 hover:bg-white/25 transition-colors" />
        </div>

        {/* ── Peek header ── */}
        <div className="relative z-10 px-5 py-3 flex items-center gap-3">
          {/* Thumbnail (peek only) */}
          {!expanded && place.photos && place.photos.length > 0 && (
            <div className="size-11 rounded-xl overflow-hidden shrink-0 border border-white/[.08]">
              <img alt=""
                src={`https://places.googleapis.com/v1/${place.photos[0].name}/media?maxHeightPx=80&maxWidthPx=80&key=${process.env.NEXT_PUBLIC_GOOGLE_MAPS_API_KEY}`}
                className="w-full h-full object-cover"
              />
            </div>
          )}

          <div className="flex-1 min-w-0">
            <p className="text-[14px] font-black text-white/90 leading-tight truncate">{place.displayName.text}</p>
            <div className="flex items-center gap-2 mt-0.5 flex-wrap">
              {place.rating && (
                <span className="text-[10px] font-bold text-amber-400">{place.rating}★</span>
              )}
              {place.primaryType && (
                <span className="text-[10px] text-white/30 capitalize">{place.primaryType.replace(/_/g, " ")}</span>
              )}
              {!expanded && (
                <>
                  {(loadingEnrich || !enrichSearched) && <span className="text-[9px] text-white/20 animate-pulse">scanning…</span>}
                  {!(loadingEnrich || !enrichSearched) && discoveredEmails.length > 0 && (
                    <span className="text-[9px] font-bold text-emerald-400/70">{discoveredEmails.length} email{discoveredEmails.length > 1 ? "s" : ""} found</span>
                  )}
                </>
              )}
            </div>
          </div>

          <div className="flex items-center gap-2 shrink-0">
            {/* Quick actions visible in peek */}
            <button
              onClick={() => onToggle(place.id)}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-[11px] font-bold transition-all"
              style={isSelected
                ? { background: "rgba(52,211,153,.12)", border: "1px solid rgba(52,211,153,.25)", color: "#34d399" }
                : { background: "rgba(255,255,255,.06)", border: "1px solid rgba(255,255,255,.09)", color: "rgba(255,255,255,.55)" }}>
              {isSelected ? <Check className="size-3" /> : <Plus className="size-3" />}
              {isSelected ? "Added" : "Add"}
            </button>
            <button
              onClick={initiateClose}
              className="size-8 rounded-full flex items-center justify-center hover:bg-white/10 transition-all"
              style={{ background: "rgba(255,255,255,.05)", border: "1px solid rgba(255,255,255,.07)" }}>
              <X className="size-3.5 text-white/40" />
            </button>
          </div>
        </div>

        {/* ── Tab bar (expanded only) ── */}
        {expanded && (
          <div className="relative z-10 px-5 pb-3 flex gap-1.5 border-b border-white/[.05] shrink-0">
            {TABS.map(tab => (
              <button key={tab.id} onClick={() => setActiveTab(tab.id)}
                className="px-4 py-1.5 rounded-xl text-[11px] font-bold transition-all"
                style={activeTab === tab.id
                  ? { background: "rgba(255,255,255,.1)", border: "1px solid rgba(255,255,255,.14)", color: "rgba(255,255,255,.88)" }
                  : { background: "transparent", border: "1px solid transparent", color: "rgba(255,255,255,.28)" }}>
                {tab.label}
              </button>
            ))}
          </div>
        )}

        {/* ── Tab content ── */}
        {expanded && (
          <div className="relative z-10 flex-1 overflow-y-auto px-5 py-5">
            {activeTab === "overview" && renderOverviewTab()}
            {activeTab === "contact"  && renderContactTab()}
            {activeTab === "audit"    && renderAuditTab()}
            {activeTab === "ai"       && renderAITab()}
          </div>
        )}
      </div>
    </>
  )
}

// ── Helpers ──────────────────────────────────────────────────────────────────

function PainPoint({
  num,
  text,
  color = "white",
}: {
  num: number
  text: React.ReactNode
  color?: "white" | "emerald"
}) {
  return (
    <div className="flex items-start gap-2">
      <span className={`text-[10px] mt-0.5 font-bold shrink-0 ${color === "emerald" ? "text-emerald-400/60" : "text-red-400/60"}`}>
        {num}.
      </span>
      <p className="text-[12px] text-white/60 leading-snug">{text}</p>
    </div>
  )
}

"use client"

import { useState, useEffect } from "react"
import {
  MapPin, Globe2, Shield, Gauge, Sparkles, Zap,
  ExternalLink, Loader2, Star,
  Copy, Phone, ChevronLeft, ChevronRight,
  BarChart3, RefreshCw, Monitor, TrendingUp,
  Users, ArrowUpRight, HelpCircle,
} from "lucide-react"
import type { Approach } from "@/app/api/leads/icebreaker/route"
import type { BusinessProfile } from "@/app/api/leads/research/route"
import type { LinkedInDecisionMaker } from "@/app/api/leads/linkedin-search/route"
import { toast } from "sonner"
import type { ContactResult } from "@/lib/contact-finder"
import type { Place } from "@/components/lead-analysis-panel"
import { extractCityFromAddress } from "@/lib/utils"

// ── Types exported for use in the find page ──────────────────────────────────

export interface AuditData {
  ssl: boolean
  speed: number
  pixel: boolean
  googleAds: boolean
  googleAnalytics: boolean
  googleTagManager: boolean
  wordpress: boolean
  shopify: boolean
  hasChat: boolean
  noH1: boolean
  noMetaDesc: boolean
  mobile?: boolean
  title: string
}

export interface PlaceEnrichment {
  auditData: AuditData | null
  auditLoading: boolean
  contacts: ContactResult[]
  contactsLoading: boolean
  contactsDone: boolean
  icebreaker: string
  research: BusinessProfile | null
  researchLoading: boolean
  linkedInProfiles: LinkedInDecisionMaker[]
  linkedInLoading: boolean
  linkedInDone: boolean
  linkedInLogs?: string[]
}

// ── Props ────────────────────────────────────────────────────────────────────

interface LeadDetailSideProps {
  place: Place
  enrichment: PlaceEnrichment
  onAuditDone: (data: AuditData) => void
  onAuditStart?: () => void
  onContactsDone: (contacts: ContactResult[]) => void
  onContactsStart?: () => void
  onIcebreakerDone: (text: string) => void
  onResearchDone: (data: BusinessProfile) => void
  onResearchStart?: () => void
  onLinkedInDone: (profiles: LinkedInDecisionMaker[], logs?: string[]) => void
  onLinkedInStart?: () => void
  searchTarget?: "b2b" | "b2c"
}

type Tab = "overview" | "contact" | "audit" | "ai"

const TABS: { id: Tab; label: string }[] = [
  { id: "overview", label: "Overview" },
  { id: "contact",  label: "Contact"  },
  { id: "audit",    label: "Audit"    },
  { id: "ai",       label: "AI"       },
]

// ── Shared style helpers ─────────────────────────────────────────────────────

const cardStyle = { background: "rgba(255,255,255,.03)", border: "1px solid rgba(255,255,255,.06)" }
const sectionHead = "text-[10px] font-black text-white/30 uppercase tracking-[.18em] mb-3"

// ── Sub-components ────────────────────────────────────────────────────────────

function PainPoint({ num, text, color = "red" }: { num: number; text: React.ReactNode; color?: "red" | "emerald" }) {
  return (
    <div className="flex items-start gap-2">
      <span className={`text-[10px] mt-0.5 font-bold shrink-0 ${color === "emerald" ? "text-emerald-400/60" : "text-red-400/60"}`}>
        {num}.
      </span>
      <p className="text-[12px] text-white/60 leading-snug">{text}</p>
    </div>
  )
}

function SignalRow({ icon: Icon, label, ok, detail }: {
  icon: React.ElementType
  label: string
  ok: boolean
  detail: string
}) {
  return (
    <div className="flex items-center gap-3 py-2.5 border-b border-white/[.04] last:border-0">
      <div
        className="flex size-7 shrink-0 items-center justify-center rounded-lg"
        style={{ background: ok ? "rgba(52,211,153,.1)" : "rgba(248,113,113,.1)" }}
      >
        <Icon className={`size-3.5 ${ok ? "text-emerald-400" : "text-red-400"}`} />
      </div>
      <span className="text-[12px] text-white/55 flex-1">{label}</span>
      <span className={`text-[11px] font-bold ${ok ? "text-emerald-400" : "text-red-400/80"}`}>{detail}</span>
    </div>
  )
}

// ── Main component ────────────────────────────────────────────────────────────

export function LeadDetailSide({
  place,
  enrichment,
  onAuditDone,
  onAuditStart,
  onContactsDone,
  onContactsStart,
  onIcebreakerDone,
  onResearchDone,
  onResearchStart,
  onLinkedInDone,
  onLinkedInStart,
  searchTarget = "b2b",
}: LeadDetailSideProps) {
  const [activeTab, setActiveTab]     = useState<Tab>("overview")
  const [activePhoto, setActivePhoto] = useState(0)
  const [generatingIce, setGeneratingIce]         = useState(false)
  const [approach, setApproach]                   = useState<Approach>("website")
  const [includeSenderCompany, setIncludeSender]  = useState(false)

  // Reset tab + photo + approach when place changes
  useEffect(() => {
    setTimeout(() => {
      setActiveTab("overview")
      setActivePhoto(0)
      setApproach("website")
    }, 0)
  }, [place.id])

  // Auto-run contact search when place changes and not yet done
  useEffect(() => {
    if (!place.websiteUri) return
    if (enrichment.contactsDone || enrichment.contactsLoading) return
    runContactSearch()
  }, [place.id])

  // Auto-run audit when place changes and not yet done
  useEffect(() => {
    if (!place.websiteUri) return
    if (enrichment.auditData || enrichment.auditLoading) return
    runAudit()
  }, [place.id])

  // Auto-run research when place changes and not yet done
  useEffect(() => {
    if (enrichment.research || enrichment.researchLoading) return
    runResearch()
  }, [place.id])

  // Auto-run LinkedIn search when place changes and not yet done
  useEffect(() => {
    if (enrichment.linkedInDone || enrichment.linkedInLoading) return
    // Signal loading to parent before async work starts
    onLinkedInDone([])  // reset previous results
    runLinkedInSearch()
  }, [place.id])

  // Auto-select recommended approach when research completes
  useEffect(() => {
    if (enrichment.research?.recommendedApproach?.id) {
      const approachId = enrichment.research.recommendedApproach.id
      setTimeout(() => setApproach(approachId), 0)
    }
  }, [enrichment.research?.recommendedApproach?.id])

  async function runResearch() {
    if (onResearchStart) onResearchStart()
    try {
      const res = await fetch("/api/leads/research", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          websiteUrl:   place.websiteUri ?? null,
          businessName: place.displayName.text,
          industry:     place.primaryType?.replace(/_/g, " ") ?? null,
          address:      place.formattedAddress,
          reviews:      place.reviews ?? [],
        }),
      })
      if (!res.ok) return
      const data = await res.json()
      if (data.profile) onResearchDone(data.profile)
    } catch { /* silent */ }
  }

  async function runAudit() {
    if (!place.websiteUri) return
    if (onAuditStart) onAuditStart()
    try {
      const res = await fetch("/api/leads/audit", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url: place.websiteUri }),
      })
      const data = await res.json()
      if (!data.error) onAuditDone(data)
    } catch {
      // silent — parent already sets auditLoading: false
    }
  }

  async function runContactSearch(bypassCache = false) {
    if (!place.websiteUri) return
    if (onContactsStart) onContactsStart()
    try {
      const res = await fetch("/api/leads/contact-search", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          websiteUrl: place.websiteUri,
          companyName: place.displayName.text,
          localNeighbors: searchTarget === "b2c",
          bypassCache,
        }),
      })
      if (!res.ok) throw new Error()
      const data = await res.json()
      onContactsDone(data.contacts ?? [])
    } catch {
      toast.error("Contact search failed")
      onContactsDone([])
    }
  }

  async function runLinkedInSearch(bypassCache = false) {
    if (onLinkedInStart) onLinkedInStart()
    try {
      const city = extractCityFromAddress(place.formattedAddress)

      // Pass research context for AI inference
      const websiteText = enrichment.research
        ? [
            enrichment.research.whatTheyDo,
            ...(enrichment.research.specializations ?? []),
            enrichment.research.positioning,
          ].filter(Boolean).join(". ")
        : undefined

      const res = await fetch("/api/leads/linkedin-search", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          companyName: place.displayName.text,
          city,
          industry:    place.primaryType?.replace(/_/g, " ") ?? null,
          websiteUrl:  place.websiteUri ?? null,
          websiteText,
          localNeighbors: searchTarget === "b2c",
          bypassCache,
        }),
      })
      if (!res.ok) throw new Error()
      const data = await res.json()
      onLinkedInDone(data.profiles ?? [], data.logs ?? [])
    } catch {
      onLinkedInDone([], ["Failed to run search fetch"])
    }
  }

  async function generateIcebreaker() {
    setGeneratingIce(true)
    try {
      const dm = enrichment.contacts.find(c => c.isDecisionMaker)
      const res = await fetch("/api/leads/icebreaker", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          approach,
          businessName:           place.displayName.text,
          address:                place.formattedAddress,
          industry:               place.primaryType?.replace(/_/g, " ") ?? null,
          rating:                 place.rating ?? null,
          reviewCount:            place.userRatingCount ?? null,
          auditData:              enrichment.auditData,
          decisionMakerFirstName: dm?.firstName ?? null,
          businessProfile:        enrichment.research ?? null,
          includeSenderCompany,
        }),
      })
      if (!res.ok) throw new Error()
      const data = await res.json()
      onIcebreakerDone(data.icebreaker ?? "")
    } catch {
      toast.error("Failed to generate message")
    } finally {
      setGeneratingIce(false)
    }
  }

  // ── Overview tab ───────────────────────────────────────────────────────────
  function renderOverviewTab() {
    return (
      <div className="space-y-5">
        {/* Photo slider */}
        {place.photos && place.photos.length > 0 && (
          <div className="relative h-44 rounded-2xl overflow-hidden group/slider select-none"
            style={{ border: "1px solid rgba(255,255,255,.07)" }}>
            <div className="flex h-full transition-transform duration-500 ease-out"
              style={{ transform: `translateX(-${activePhoto * 100}%)` }}>
              {place.photos.map((photo, i) => (
                <img key={i} alt=""
                  src={`https://places.googleapis.com/v1/${photo.name}/media?maxHeightPx=400&maxWidthPx=700&key=${process.env.NEXT_PUBLIC_GOOGLE_MAPS_API_KEY}`}
                  className="w-full h-full object-cover shrink-0"
                />
              ))}
            </div>
            <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent" />
            {place.photos.length > 1 && (
              <>
                <button
                  onClick={() => setActivePhoto(p => Math.max(0, p - 1))}
                  className="absolute left-2 top-1/2 -translate-y-1/2 size-7 rounded-full bg-black/40 backdrop-blur border border-white/10 flex items-center justify-center opacity-0 group-hover/slider:opacity-100 transition-opacity"
                >
                  <ChevronLeft className="size-3.5 text-white" />
                </button>
                <button
                  onClick={() => setActivePhoto(p => Math.min(place.photos!.length - 1, p + 1))}
