  })

  if (!goal || !goal.user?.companyDesc) {
    onProgress?.("Error: Agency profile or description not found. Engine aborted.")
    return results
  }

  try {
    const apiKey = process.env.NEXT_PUBLIC_GOOGLE_MAPS_API_KEY
    if (!apiKey) {
      onProgress?.("Error: Google Maps API key not configured.")
      return results
    }

    const personaConfig = goal.personaConfig as any || {}

    onProgress?.(`Analyzing agency profile: "${goal.user.companyDesc.slice(0, 50)}..."`)

    // 1. Generate an AI strategy for this run
    const strategy = await generateAutoSearchQuery({
      companyDesc: goal.user.companyDesc,
      personaConfig: personaConfig,
      targetRegions: personaConfig.targetRegions,
    })

    if (!strategy?.query || !strategy?.location) {
      onProgress?.("Failed to generate a valid Maps query strategy.")
      return results
    }

    onProgress?.(`Generated strategy: "${strategy.query} in ${strategy.location}"`)
    onProgress?.("Querying Google Places API...")

    // 2. Fetch businesses from Google Places
    const res = await fetch("https://places.googleapis.com/v1/places:searchText", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Goog-Api-Key": apiKey,
        "X-Goog-FieldMask": [
          "places.id", "places.displayName", "places.formattedAddress",
          "places.websiteUri", "places.nationalPhoneNumber",
          "places.rating", "places.userRatingCount",
        ].join(","),
      },
      body: JSON.stringify({
        textQuery: `${strategy.query} in ${strategy.location}`,
        maxResultCount: 20,
      }),
    })

    if (!res.ok) {
      onProgress?.(`Google Places API returned status ${res.status}`)
      return results
    }

    const data = await res.json()
    const places: Place[] = data.places ?? []
    if (places.length === 0) {
      onProgress?.("No places found for this query.")
      return results
    }

    onProgress?.(`Found ${places.length} businesses. Filtering out existing leads...`)

    // 3. Filter out businesses already imported for this user
    const existingIds = await prisma.lead.findMany({
      where: { userId: goal.user.id, googlePlaceId: { in: places.map(p => p.id) } },
      select: { googlePlaceId: true },
    }).then(rows => new Set(rows.map(r => r.googlePlaceId)))

    const newPlaces = places.filter(p => !existingIds.has(p.id))
    if (newPlaces.length === 0) {
      onProgress?.("All found businesses were already in your database. Mission accomplished.")
      return results
    }

    const leadsPerCycle = Math.max(1, Math.min(20, Number(personaConfig.leadsPerCycle) || 1))
    const selectedPlaces = newPlaces.slice(0, leadsPerCycle)

    onProgress?.(`Found ${newPlaces.length} new leads. Processing ${selectedPlaces.length} this cycle (limit: ${leadsPerCycle})...`)

    // 4. Create leads
    const created = await prisma.$transaction(
      selectedPlaces.map(p =>
        prisma.lead.create({
          data: {
            userId: goal.user!.id,
            email: emailFromPlace(p),
            company: p.displayName.text,
            website: p.websiteUri ?? null,
            companyDesc: p.formattedAddress ?? null,
            googlePlaceId: p.id,
            notes: [
              p.formattedAddress,
              p.nationalPhoneNumber,
              p.rating != null ? `Rating: ${p.rating}/5 (${p.userRatingCount} reviews)` : null,
            ].filter(Boolean).join("\n"),
          },
        })
      )
    )

    // 5. Get default sequence
    const sequence = await prisma.sequence.findFirst({
      where: { userId: goal.user.id },
      orderBy: { createdAt: "desc" }
    })

    if (!sequence) {
      onProgress?.("Warning: No active email sequence found. Leads imported, but campaign not created.")
      return results
    }

    // 6. Create a new autonomous campaign
    const label = now.toLocaleDateString("en-US", { month: "short", day: "numeric" })
    const campaignName = `${strategy.query} in ${strategy.location}`

    onProgress?.(`Creating Campaign "${campaignName} – ${label}" and attaching sequence...`)

    const campaign = await prisma.campaign.create({
      data: {
        userId: goal.user.id,
        name: `${campaignName} – ${label}`,
        sequenceId: sequence.id,
        autonomous: true,
        totalLeads: created.length,
        campaignLeads: {
          createMany: {
            data: created.map(l => ({ leadId: l.id })),
            skipDuplicates: true,
          },
        },
      },
    })

    results.campaigns++

    onProgress?.(`Campaign created. Enriching ${created.length} new leads and drafting personalized emails in the background...`)

    // 7. Enrich leads and auto-generate emails
    enrichLeadsInBackground(created.map(l => l.id)).catch(err => {
      console.error(`Background enrichment failed for auto-search:`, err)
    })

    onProgress?.("All leads processed and queued! Autonomous Engine run complete.")

    results.searches++
    results.leads += created.length
  } catch (err) {
    onProgress?.(`Critical Error: ${err instanceof Error ? err.message : String(err)}`)
    console.error(`Autonomous Engine failed for user ${goal.userId}:`, err)
  }

  return results
}

export async function runAutoSearches(): Promise<{ searches: number; leads: number; campaigns: number }> {
  const results = { searches: 0, leads: 0, campaigns: 0 }

  // Find all users who have the autonomous engine enabled
  const agentGoals = await prisma.agentGoal.findMany({
    where: { autoProspectingEnabled: true },
    select: { userId: true }
  })

  for (const goal of agentGoals) {
    const res = await runAutoSearchForUser(goal.userId)
    results.searches += res.searches
    results.leads += res.leads
    results.campaigns += res.campaigns
  }

  return results
}

import { ImapFlow } from "imapflow"
import { prisma } from "./db"
import { generateBattleCard } from "./ai"
import { processReply } from "./agent"

function getHeaderValue(headersStr: string, name: string): string {
  const lines = headersStr.split(/\r?\n/)
  let value = ""
  let found = false
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    if (line.toLowerCase().startsWith(`${name.toLowerCase()}:`)) {
      value = line.slice(name.length + 1).trim()
      found = true
    } else if (found) {
      if (/^\s/.test(line)) {
        value += " " + line.trim()
      } else {
        break
      }
    }
  }
  return value
}

function decodeQuotedPrintable(str: string): string {
  let result = str.replace(/=\r?\n/g, "")
  result = result.replace(/=([0-9A-F]{2})/gi, (match, hex) => {
    return String.fromCharCode(parseInt(hex, 16))
  })
  try {
    const bytes = []
    for (let i = 0; i < result.length; i++) {
      bytes.push(result.charCodeAt(i))
    }
    return Buffer.from(bytes).toString("utf8")
  } catch {
    return result
  }
}

function cleanHtmlReply(html: string): string {
  const quoteMarkers = [
    '<div class="gmail_quote',
    '<div class="gmail_attr',
    '<blockquote',
    '<div id="appendonsend"',
    'id="divRplyFwdMsg"',
    '<hr'
  ]

  let cleanHtml = html
  let lowestIndex = -1

  for (const marker of quoteMarkers) {
    const idx = cleanHtml.indexOf(marker)
    if (idx !== -1 && (lowestIndex === -1 || idx < lowestIndex)) {
      lowestIndex = idx
    }
  }

  if (lowestIndex !== -1) {
    cleanHtml = cleanHtml.slice(0, lowestIndex)
  }

  const text = cleanHtml
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/p>/gi, "\n")
    .replace(/<\/div>/gi, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/gi, " ")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, "\"")

  return text.split("\n").map(l => l.trim()).filter(Boolean).join("\n").trim()
}

function extractHtmlPart(raw: string): string | null {
  if (!raw.includes("Content-Type:")) {
    return null
  }

  const lines = raw.split(/\r?\n/)
  let boundary = ""
  for (const line of lines) {
    if (line.startsWith("--") && line.length > 10) {
      boundary = line.trim()
      break
    }
  }

  if (!boundary) return null

  const parts = raw.split(boundary)
  for (const part of parts) {
    if (part.toLowerCase().includes("content-type: text/html")) {
      const match = part.match(/\r?\n\r?\n([\s\S]*)/i)
      if (match) {
        return match[1].trim()
      }
    }
  }
  return null
}

function cleanReplyBody(raw: string): string {
  const htmlPart = extractHtmlPart(raw)
  if (htmlPart) {
    const decodedHtml = decodeQuotedPrintable(htmlPart)
    const cleanedHtmlText = cleanHtmlReply(decodedHtml)
    if (cleanedHtmlText) return cleanedHtmlText
  }

  if (!raw.includes("Content-Type:")) {
    return raw.trim()
  }

  const lines = raw.split(/\r?\n/)
  let boundary = ""
  for (const line of lines) {
    if (line.startsWith("--") && line.length > 10) {
      boundary = line.trim()
      break
    }
  }

  if (!boundary) return raw.trim()

  const parts = raw.split(boundary)
  for (const part of parts) {
    if (part.toLowerCase().includes("content-type: text/plain")) {
      const match = part.match(/\r?\n\r?\n([\s\S]*)/i)
      if (match) {
        const text = decodeQuotedPrintable(match[1].trim())
        return text
          .split("\n")
          .filter(line => {
            const l = line.trim()
            return !l.startsWith(">") && !l.startsWith("On ") && !l.startsWith("wrote:")
          })
          .join("\n")
          .trim()
      }
    }
  }

  return raw.trim()
}

export async function detectReplies(userId?: string): Promise<{ found: number; errors: number }> {
  const whereClause: Record<string, unknown> = {
    fromEmail: { not: null },
    smtpPass: { not: null },
  }
  if (userId) {
    whereClause.id = userId
  }

  const users = await prisma.user.findMany({
    where: whereClause,
    select: {
      id: true,
      fromEmail: true,
      smtpPass: true,
    },
  })


  const targets: { userId: string; user: string; pass: string }[] = users.map(u => ({
    userId: u.id,
    user: u.fromEmail!,
    pass: u.smtpPass!,
  }))

  if (targets.length === 0 && process.env.GMAIL_USER && process.env.GMAIL_APP_PASSWORD) {
    targets.push({
      userId: userId || "",
      user: process.env.GMAIL_USER,
      pass: process.env.GMAIL_APP_PASSWORD,
    })
  }

  let found = 0
  let errors = 0

  for (const target of targets) {
    const client = new ImapFlow({
      host: "imap.gmail.com",
      port: 993,
      secure: true,
      auth: { user: target.user, pass: target.pass },
      logger: false,
    })

    try {
      await client.connect()
      const lock = await client.getMailboxLock("INBOX")

      try {
        const since = new Date(Date.now() - 25 * 60 * 60 * 1000)

        for await (const msg of client.fetch({ since }, { headers: true, envelope: true, bodyParts: ["text"] })) {
          try {
            const headersStr = Buffer.isBuffer(msg.headers) ? msg.headers.toString() : String(msg.headers || "")
            const inReplyTo = getHeaderValue(headersStr, "in-reply-to")
            const references = getHeaderValue(headersStr, "references")
            const combined = `${inReplyTo} ${references}`

            const ids = Array.from(combined.matchAll(/<([^>]+)>/g)).map(m => m[1])
            if (ids.length === 0) continue

            const sentEmail = await prisma.email.findFirst({
              where: {
                messageId: { in: ids.map(id => `<${id}>`) },
                status: { notIn: ["REPLIED", "FAILED"] },
                ...(target.userId ? { lead: { userId: target.userId } } : {}),
              },
              include: {
                lead: {
                  include: {
                    campaignLeads: { select: { campaignId: true } },
                    user: { select: { name: true, agencyName: true, companyName: true, companyDesc: true, tone: true } },
                  },
                },
              },
            })

            if (!sentEmail) continue

            const lead = sentEmail.lead
            const campaignIds = lead.campaignLeads.map(cl => cl.campaignId)

            // Extract reply body from IMAP message
            let replyBody = ""
            try {
              const textPart = (msg.bodyParts as any)?.get?.("text")
              if (textPart) {
                const rawBody = Buffer.isBuffer(textPart) ? textPart.toString("utf8") : String(textPart)
                replyBody = cleanReplyBody(rawBody).slice(0, 2000)
              }
            } catch { /* body extraction optional */ }

            const fromEmail = msg.envelope?.from?.[0]?.address ?? lead.email
            const replySubject = msg.envelope?.subject ?? `Re: ${sentEmail.subject}`

            // 1. Double check if we already have a reply for this sent email (concurrency lock)
            const existingReply = await prisma.reply.findFirst({
              where: { emailId: sentEmail.id },
            })
            if (existingReply) continue

            // 2. Mark sent email as REPLIED immediately to lock it
            await prisma.email.update({
              where: { id: sentEmail.id },
              data: { status: "REPLIED", repliedAt: new Date(), replySnippet: replyBody.slice(0, 300) },
            })

            // 3. Create the reply record immediately
            const newReply = await prisma.reply.create({
              data: {
                leadId: lead.id,
                emailId: sentEmail.id,
                fromEmail,
                subject: replySubject,
                body: replyBody || "(reply body not captured)",
                receivedAt: msg.envelope?.date ?? new Date(),
              },
            })

            // 4. Generate battle card via AI (slow call)
            let battleCardJson: string | null = null
            try {
              const card = await generateBattleCard({
                leadName: [lead.firstName, lead.lastName].filter(Boolean).join(" ") || lead.email,
                company: lead.company || "their company",
                industry: lead.industry || "business",
                website: lead.website,
                painPoint: lead.painPoint,
                recentNews: lead.recentNews,
                originalEmailSubject: sentEmail.subject,
                originalEmailBody: sentEmail.body,
                replyBody: replyBody || "(reply body not captured)",
                senderName: lead.user.name || "Your Name",
                senderCompany: lead.user.agencyName || lead.user.companyName || "Your Company",
                senderService: lead.user.companyDesc || "our services",
              })
              battleCardJson = JSON.stringify(card)
            } catch { /* battle card generation optional */ }

            // 5. Update lead status + store battle card + run remaining updates
            await Promise.all([
              prisma.lead.update({
                where: { id: lead.id },
                data: {
                  status: "REPLIED",
                  ...(battleCardJson ? { battleCard: battleCardJson } : {}),
                },
              }),
              // Lead replied — cancel any remaining unsent sequence templates
              prisma.email.deleteMany({
                where: { leadId: lead.id, status: { in: ["QUEUED", "DRAFT"] } },
              }),
              campaignIds.length > 0
                ? prisma.campaign.updateMany({
                    where: { id: { in: campaignIds } },
                    data: { replies: { increment: 1 } },
                  })
                : Promise.resolve(),
              prisma.activity.create({
                data: {
                  leadId: lead.id,
                  type: "REPLY_RECEIVED",
                  note: replySubject,
                  metadata: { fromEmail, snippet: replyBody.slice(0, 150) },
                },
              }),
              ...(battleCardJson ? [prisma.activity.create({
                data: {
                  leadId: lead.id,
                  type: "BATTLE_CARD_GENERATED",
                  note: "Battle card auto-generated from reply",
                },
              })] : []),
            ])

            // Fire agent processing asynchronously
            processReply(newReply.id).catch(e => console.error("Agent processReply error:", e))

            found++
          } catch (e) {
            console.error("Error processing reply message:", e)
            errors++
          }
        }
      } finally {
        lock.release()
      }
    } catch (e) {
      console.error(`IMAP connection error for ${target.user}:`, e)
      errors++
    } finally {
      try { await client.logout() } catch {}
    }
  }

  return { found, errors }
}

import { prisma } from "@/lib/db"
import { findContacts } from "@/lib/contact-finder"
